#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize)]
pub struct RenderArtifactCacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub skipped_oversized: u64,
    pub entries: usize,
    pub bytes: usize,
}

trait Type3ProgramCacheValue {
    fn approximate_bytes(&self) -> usize;
}

enum Type3ProgramState<T: Type3ProgramCacheValue> {
    Compiling,
    Compiled(Arc<T>),
    Failed(String),
}

#[cfg(test)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Type3ProgramLifecycle {
    Unvisited,
    Compiling,
    Compiled,
    Failed,
}

impl<T: Type3ProgramCacheValue> Type3ProgramState<T> {
    fn cached_value(&self) -> Option<Arc<T>> {
        match self {
            Self::Compiled(value) => Some(Arc::clone(value)),
            Self::Compiling | Self::Failed(_) => None,
        }
    }

    #[cfg(test)]
    fn lifecycle(&self) -> Type3ProgramLifecycle {
        match self {
            Self::Compiling => Type3ProgramLifecycle::Compiling,
            Self::Compiled(_) => Type3ProgramLifecycle::Compiled,
            Self::Failed(_) => Type3ProgramLifecycle::Failed,
        }
    }
}

impl<T: Type3ProgramCacheValue> Clone for Type3ProgramState<T> {
    fn clone(&self) -> Self {
        match self {
            Self::Compiling => Self::Compiling,
            Self::Compiled(value) => Self::Compiled(Arc::clone(value)),
            Self::Failed(reason) => Self::Failed(reason.clone()),
        }
    }
}

struct Type3ProgramCache<T: Type3ProgramCacheValue> {
    entries: HashMap<String, Type3ProgramState<T>>,
    order: VecDeque<String>,
    bytes: usize,
    stats: RenderArtifactCacheStats,
}

impl<T: Type3ProgramCacheValue> Default for Type3ProgramCache<T> {
    fn default() -> Self {
        Self {
            entries: HashMap::new(),
            order: VecDeque::new(),
            bytes: 0,
            stats: RenderArtifactCacheStats::default(),
        }
    }
}

impl<T: Type3ProgramCacheValue> Clone for Type3ProgramCache<T> {
    fn clone(&self) -> Self {
        Self {
            entries: self.entries.clone(),
            order: self.order.clone(),
            bytes: self.bytes,
            stats: RenderArtifactCacheStats::default(),
        }
    }
}

impl<T: Type3ProgramCacheValue> Type3ProgramCache<T> {
    const MAX_ENTRIES: usize = 1_024;
    const MAX_BYTES: usize = PROGRAM_CACHE_MAX_BYTES;
    const MAX_ENTRY_BYTES: usize = PROGRAM_CACHE_MAX_ENTRY_BYTES;

    fn entry_bytes(key: &str, value: &Type3ProgramState<T>) -> usize {
        std::mem::size_of::<String>()
            .saturating_mul(2)
            .saturating_add(key.len().saturating_mul(2))
            .saturating_add(std::mem::size_of::<Type3ProgramState<T>>())
            .saturating_add(match value {
                Type3ProgramState::Compiled(value) => value.approximate_bytes(),
                Type3ProgramState::Failed(reason) => reason.len(),
                Type3ProgramState::Compiling => 0,
            })
    }

    fn get(&mut self, key: &str) -> Option<Option<Arc<T>>> {
        let hit = self.entries.get(key).map(Type3ProgramState::cached_value);
        if hit.is_some() {
            self.stats.hits = self.stats.hits.saturating_add(1);
            self.touch(key);
        } else {
            self.stats.misses = self.stats.misses.saturating_add(1);
        }
        hit
    }

    fn insert(&mut self, key: String, value: Option<Arc<T>>) {
        let state = match value {
            Some(value) => Type3ProgramState::Compiled(value),
            None => Type3ProgramState::Failed("Type 3 program unavailable".to_string()),
        };
        self.insert_state(key, state);
    }

    fn insert_compiling(&mut self, key: String) {
        self.insert_state(key, Type3ProgramState::Compiling);
    }

    fn insert_failed(&mut self, key: String, reason: impl Into<String>) {
        self.insert_state(key, Type3ProgramState::Failed(reason.into()));
    }

    fn insert_state(&mut self, key: String, value: Type3ProgramState<T>) {
        let entry_bytes = Self::entry_bytes(&key, &value);
        if entry_bytes > Self::MAX_ENTRY_BYTES {
            self.stats.skipped_oversized = self.stats.skipped_oversized.saturating_add(1);
            return;
        }
        if let Some(previous) = self.entries.remove(&key) {
            self.bytes = self
                .bytes
                .saturating_sub(Self::entry_bytes(&key, &previous));
            self.remove_ordered(&key);
        }
        while self.entries.len() >= Self::MAX_ENTRIES
            || self.bytes.saturating_add(entry_bytes) > Self::MAX_BYTES
        {
            if self.evict_one() {
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
        if self.entries.len() < Self::MAX_ENTRIES
            && self.bytes.saturating_add(entry_bytes) <= Self::MAX_BYTES
        {
            self.order.push_back(key.clone());
            self.bytes = self.bytes.saturating_add(entry_bytes);
            self.entries.insert(key, value);
        }
    }

    #[cfg(test)]
    fn lifecycle(&self, key: &str) -> Type3ProgramLifecycle {
        self.entries.get(key).map_or(
            Type3ProgramLifecycle::Unvisited,
            Type3ProgramState::lifecycle,
        )
    }

    fn failure_reason(&self, key: &str) -> Option<&str> {
        match self.entries.get(key) {
            Some(Type3ProgramState::Failed(reason)) => Some(reason),
            Some(Type3ProgramState::Compiling | Type3ProgramState::Compiled(_)) | None => None,
        }
    }

    fn absorb_from(&mut self, mut other: Self) {
        merge_artifact_cache_counts(&mut self.stats, other.stats);
        for key in std::mem::take(&mut other.order) {
            if let Some(value) = other.entries.remove(&key) {
                self.insert_state(key, value);
            }
        }
        for (key, value) in other.entries {
            self.insert_state(key, value);
        }
    }

    #[cfg(test)]
    fn len(&self) -> usize {
        self.entries.len()
    }

    fn clear(&mut self) {
        self.entries.clear();
        self.order.clear();
        self.bytes = 0;
        self.stats = RenderArtifactCacheStats::default();
    }

    fn stats(&self) -> RenderArtifactCacheStats {
        RenderArtifactCacheStats {
            entries: self.entries.len(),
            bytes: self.bytes,
            ..self.stats
        }
    }

    fn bytes(&self) -> usize {
        self.bytes
    }

    fn oldest_entry_bytes(&self) -> Option<usize> {
        self.order.front().and_then(|key| {
            self.entries
                .get(key)
                .map(|value| Self::entry_bytes(key, value))
        })
    }

    fn evict_one_lru(&mut self) -> bool {
        self.evict_one()
    }

    fn remove_entries_matching(&mut self, markers: &[String]) {
        let removed_keys = self
            .entries
            .keys()
            .filter(|key| cache_key_matches_page_marker(key, markers))
            .cloned()
            .collect::<HashSet<_>>();
        if removed_keys.is_empty() {
            return;
        }

        let mut removed_count = 0u64;
        for key in &removed_keys {
            if let Some(removed) = self.entries.remove(key) {
                self.bytes = self.bytes.saturating_sub(Self::entry_bytes(key, &removed));
                removed_count = removed_count.saturating_add(1);
            }
        }
        self.order.retain(|key| !removed_keys.contains(key));
        self.stats.evictions = self.stats.evictions.saturating_add(removed_count);
    }

    fn trim_to_capacity(&mut self) {
        while self.entries.len() > Self::MAX_ENTRIES || self.bytes > Self::MAX_BYTES {
            if self.evict_one() {
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
    }

    fn touch(&mut self, key: &str) {
        self.remove_ordered(key);
        self.order.push_back(key.to_string());
    }

    fn remove_ordered(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|item| item == key) {
            self.order.remove(pos);
        }
    }

    fn evict_one(&mut self) -> bool {
        while let Some(victim) = self.order.pop_front() {
            if let Some(removed) = self.entries.remove(&victim) {
                self.bytes = self
                    .bytes
                    .saturating_sub(Self::entry_bytes(&victim, &removed));
                return true;
            }
        }
        false
    }
}

fn merge_artifact_cache_counts(dst: &mut RenderArtifactCacheStats, src: RenderArtifactCacheStats) {
    dst.hits = dst.hits.saturating_add(src.hits);
    dst.misses = dst.misses.saturating_add(src.misses);
    dst.evictions = dst.evictions.saturating_add(src.evictions);
    dst.skipped_oversized = dst.skipped_oversized.saturating_add(src.skipped_oversized);
}

/// Per-document renderer scratch reused across sequential page renders.
///
/// The normal `render_page*` entry points keep the historical per-page cache
/// behavior. Callers that render many pages from one already-open document can
/// pass this cache to the `*_with_document_cache` variants to reuse font bytes,
/// font resolvers, glyph outlines/masks, Type3 glyph geometry/masks, path
/// raster masks, image/shading/Form/pattern programs, retained display lists,
/// and bounded offscreen buffers without changing rendering semantics. The
/// cache is intentionally `&mut` rather than shared behind locks: a caller may
/// keep one cache per document worker, while parallel rendering uses separate
/// caches and remains deterministic.
pub struct RenderDocumentCache {
    glyph_cache: GlyphCache,
    glyph_mask_cache: GlyphMaskCache,
    type3_mask_cache: Type3MaskCache,
    type3_rendered_cache: Type3RenderedGlyphCache,
    path_fill_mask_cache: PathFillMaskCache,
    path_stroke_mask_cache: PathStrokeMaskCache,
    path_clip_node_cache: PathClipNodeCache,
    font_bytes_cache: HashMap<String, Option<Arc<Vec<u8>>>>,
    font_bytes_cache_order: VecDeque<String>,
    font_bytes_cache_bytes: usize,
    font_bytes_cache_stats: RenderArtifactCacheStats,
    font_resolver_cache: HashMap<String, Arc<FontResolver>>,
    font_resolver_cache_order: VecDeque<String>,
    font_resolver_cache_bytes: usize,
    font_resolver_cache_stats: RenderArtifactCacheStats,
    type3_geometry_cache: Type3ProgramCache<Type3GlyphGeometry>,
    type3_charproc_cache: Type3ProgramCache<Type3CharProc>,
    type3_retained_charproc_cache: Type3ProgramCache<Type3RetainedCharProcPlan>,
    image_xobject_cache: HashMap<String, Arc<RawImage>>,
    image_xobject_cache_order: VecDeque<String>,
    image_xobject_cache_bytes: usize,
    image_xobject_cache_stats: RenderArtifactCacheStats,
    scaled_image_cache: HashMap<String, Arc<RawImage>>,
    scaled_image_cache_order: VecDeque<String>,
    scaled_image_cache_bytes: usize,
    scaled_image_cache_stats: RenderArtifactCacheStats,
    smask_group_cache: HashMap<String, Arc<AlphaMask>>,
    smask_group_cache_order: VecDeque<String>,
    smask_group_cache_bytes: usize,
    smask_group_cache_stats: RenderArtifactCacheStats,
    shading_mesh_cache: HashMap<String, Arc<Vec<u8>>>,
    shading_mesh_cache_order: VecDeque<String>,
    shading_mesh_cache_bytes: usize,
    shading_mesh_cache_stats: RenderArtifactCacheStats,
    form_xobject_program_cache: HashMap<String, Option<Arc<FormXObjectProgram>>>,
    form_xobject_program_cache_order: VecDeque<String>,
    form_xobject_program_cache_bytes: usize,
    form_xobject_program_cache_stats: RenderArtifactCacheStats,
    tiling_pattern_program_cache: HashMap<String, Option<Arc<TilingPatternProgram>>>,
    tiling_pattern_program_cache_order: VecDeque<String>,
    tiling_pattern_program_cache_bytes: usize,
    tiling_pattern_program_cache_stats: RenderArtifactCacheStats,
    annotation_appearance_program_cache: HashMap<String, Option<Arc<FormXObjectProgram>>>,
    annotation_appearance_program_cache_order: VecDeque<String>,
    annotation_appearance_program_cache_bytes: usize,
    annotation_appearance_program_cache_stats: RenderArtifactCacheStats,
    offscreen_buffer_pool: Vec<PixelBuffer>,
    display_list_cache: HashMap<String, Arc<DisplayList>>,
    display_list_cache_order: VecDeque<String>,
    display_list_cache_bytes: usize,
    display_list_cache_stats: RenderArtifactCacheStats,
    display_list_raster_cache: RenderCache,
    transparent_page_group_cache: HashMap<String, bool>,
    transparent_page_group_cache_order: VecDeque<String>,
    clip_dag_stats: ClipDagStats,
    document_revision: Option<RevisionId>,
    dependency_graph: Option<RenderDependencyGraph>,
    source_identities: HashMap<(u32, u16), ObjectIdentityId>,
    source_cache_markers: HashMap<ObjectIdentityId, Vec<String>>,
    font_substitution_log: FontSubstitutionLog,
}

