    pub fn aggregate_resource_cache_bytes(&self) -> usize {
        self.font_bytes_cache_bytes
            .saturating_add(self.font_resolver_cache_bytes)
            .saturating_add(self.glyph_cache.current_bytes())
            .saturating_add(self.glyph_mask_cache.bytes())
            .saturating_add(self.type3_geometry_cache.bytes())
            .saturating_add(self.type3_charproc_cache.bytes())
            .saturating_add(self.type3_retained_charproc_cache.bytes())
            .saturating_add(self.type3_mask_cache.bytes())
            .saturating_add(self.type3_rendered_cache.bytes())
            .saturating_add(self.path_fill_mask_cache.bytes())
            .saturating_add(self.path_stroke_mask_cache.bytes())
            .saturating_add(self.display_list_cache_bytes)
            .saturating_add(self.path_clip_node_cache.bytes())
            .saturating_add(self.image_xobject_cache_bytes)
            .saturating_add(self.scaled_image_cache_bytes)
            .saturating_add(self.smask_group_cache_bytes)
            .saturating_add(self.shading_mesh_cache_bytes)
            .saturating_add(self.form_xobject_program_cache_bytes)
            .saturating_add(self.tiling_pattern_program_cache_bytes)
            .saturating_add(self.annotation_appearance_program_cache_bytes)
    }

    fn enforce_bounded_maps(&mut self, budget: RenderResourceBudget) {
        const FONT_BYTES_BUDGET: usize = 64 * 1024 * 1024;
        const FONT_RESOLVER_ENTRIES: usize = 2_048;
        const FORM_PROGRAM_ENTRIES: usize = 1_024;
        const PATTERN_PROGRAM_ENTRIES: usize = 1_024;
        const ANNOTATION_APPEARANCE_PROGRAM_ENTRIES: usize = 1_024;
        const DISPLAY_LIST_ENTRIES: usize = 512;
        const OFFSCREEN_POOL_BYTES: usize = 64 * 1024 * 1024;
        const DISPLAY_LIST_CACHE_BYTES: usize = 128 * 1024 * 1024;
        let max_cache_bytes = budget_to_usize(budget.max_cache_bytes);

        while self.font_bytes_cache_bytes > FONT_BYTES_BUDGET.min(max_cache_bytes) {
            if pop_front_font_bytes_cache_entry(
                &mut self.font_bytes_cache,
                &mut self.font_bytes_cache_order,
                &mut self.font_bytes_cache_bytes,
            ) {
                self.font_bytes_cache_stats.evictions =
                    self.font_bytes_cache_stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
        self.font_resolver_cache_stats.evictions = self
            .font_resolver_cache_stats
            .evictions
            .saturating_add(trim_ordered_cache_entries(
                &mut self.font_resolver_cache,
                &mut self.font_resolver_cache_order,
                &mut self.font_resolver_cache_bytes,
                FONT_RESOLVER_ENTRIES,
                |_| font_resolver_cache_entry_bytes(),
            ) as u64);
        self.type3_geometry_cache.trim_to_capacity();
        self.type3_charproc_cache.trim_to_capacity();
        self.type3_retained_charproc_cache.trim_to_capacity();
        self.form_xobject_program_cache_stats.evictions = self
            .form_xobject_program_cache_stats
            .evictions
            .saturating_add(trim_program_cache_entries(
                &mut self.form_xobject_program_cache,
                &mut self.form_xobject_program_cache_order,
                &mut self.form_xobject_program_cache_bytes,
                FORM_PROGRAM_ENTRIES,
                form_xobject_program_cache_entry_bytes,
            ) as u64);
        self.tiling_pattern_program_cache_stats.evictions = self
            .tiling_pattern_program_cache_stats
            .evictions
            .saturating_add(trim_program_cache_entries(
                &mut self.tiling_pattern_program_cache,
                &mut self.tiling_pattern_program_cache_order,
                &mut self.tiling_pattern_program_cache_bytes,
                PATTERN_PROGRAM_ENTRIES,
                tiling_pattern_program_cache_entry_bytes,
            ) as u64);
        self.annotation_appearance_program_cache_stats.evictions = self
            .annotation_appearance_program_cache_stats
            .evictions
            .saturating_add(trim_program_cache_entries(
                &mut self.annotation_appearance_program_cache,
                &mut self.annotation_appearance_program_cache_order,
                &mut self.annotation_appearance_program_cache_bytes,
                ANNOTATION_APPEARANCE_PROGRAM_ENTRIES,
                form_xobject_program_cache_entry_bytes,
            ) as u64);
        while self.transparent_page_group_cache.len() > TRANSPARENT_PAGE_GROUP_CACHE_ENTRIES {
            if !pop_front_transparent_page_group_cache_entry(
                &mut self.transparent_page_group_cache,
                &mut self.transparent_page_group_cache_order,
            ) {
                break;
            }
        }

        self.display_list_cache_stats.evictions = self
            .display_list_cache_stats
            .evictions
            .saturating_add(trim_ordered_cache_entries(
                &mut self.display_list_cache,
                &mut self.display_list_cache_order,
                &mut self.display_list_cache_bytes,
                DISPLAY_LIST_ENTRIES,
                display_list_cache_entry_bytes,
            ) as u64);
        while self.display_list_cache_bytes > DISPLAY_LIST_CACHE_BYTES.min(max_cache_bytes) {
            if pop_front_display_list_cache_entry(
                &mut self.display_list_cache,
                &mut self.display_list_cache_order,
                &mut self.display_list_cache_bytes,
            ) {
                self.display_list_cache_stats.evictions =
                    self.display_list_cache_stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
        while self.offscreen_buffer_pool_bytes() > OFFSCREEN_POOL_BYTES.min(max_cache_bytes) {
            if self.offscreen_buffer_pool.pop().is_none() {
                break;
            }
        }
        while self.aggregate_resource_cache_bytes() > max_cache_bytes {
            if !self.evict_one_aggregate_resource_cache_entry() {
                break;
            }
        }
    }

    fn evict_one_aggregate_resource_cache_entry(&mut self) -> bool {
        let mut candidate: Option<(u8, usize)> = None;
        let mut consider = |kind: u8, bytes: Option<usize>| {
            if let Some(bytes) = bytes {
                let should_replace = candidate
                    .map(|(existing_kind, existing_bytes)| {
                        bytes > existing_bytes || (bytes == existing_bytes && kind < existing_kind)
                    })
                    .unwrap_or(true);
                if should_replace {
                    candidate = Some((kind, bytes));
                }
            }
        };

        consider(
            0,
            self.font_bytes_cache_order
                .front()
                .and_then(|key| self.font_bytes_cache.get(key))
                .map(font_bytes_cache_entry_bytes),
        );
        consider(
            1,
            self.font_resolver_cache_order
                .front()
                .and_then(|key| self.font_resolver_cache.get(key))
                .map(|_| font_resolver_cache_entry_bytes()),
        );
        consider(2, self.glyph_cache.oldest_entry_bytes());
        consider(3, self.glyph_mask_cache.oldest_entry_bytes());
        consider(4, self.type3_mask_cache.oldest_entry_bytes());
        consider(5, self.type3_rendered_cache.oldest_entry_bytes());
        consider(6, self.path_fill_mask_cache.oldest_entry_bytes());
        consider(7, self.path_stroke_mask_cache.oldest_entry_bytes());
        consider(
            8,
            self.display_list_cache_order
                .front()
                .and_then(|key| self.display_list_cache.get(key))
                .map(display_list_cache_entry_bytes),
        );
        consider(9, self.path_clip_node_cache.oldest_entry_bytes());
        consider(
            10,
            self.image_xobject_cache_order
                .front()
                .and_then(|key| self.image_xobject_cache.get(key))
                .map(|raw| raw.byte_count()),
        );
        consider(
            11,
            self.scaled_image_cache_order
                .front()
                .and_then(|key| self.scaled_image_cache.get(key))
                .map(|raw| raw.byte_count()),
        );
        consider(
            12,
            self.smask_group_cache_order
                .front()
                .and_then(|key| self.smask_group_cache.get(key))
                .map(|mask| mask.approximate_bytes()),
        );
        consider(
            13,
            self.shading_mesh_cache_order
                .front()
                .and_then(|key| self.shading_mesh_cache.get(key))
                .map(|bytes| bytes.len()),
        );
        consider(
            14,
            self.form_xobject_program_cache_order
                .front()
                .and_then(|key| self.form_xobject_program_cache.get(key))
                .map(form_xobject_program_cache_entry_bytes),
        );
        consider(
            15,
            self.tiling_pattern_program_cache_order
                .front()
                .and_then(|key| self.tiling_pattern_program_cache.get(key))
                .map(tiling_pattern_program_cache_entry_bytes),
        );
        consider(
            16,
            self.annotation_appearance_program_cache_order
                .front()
                .and_then(|key| self.annotation_appearance_program_cache.get(key))
                .map(form_xobject_program_cache_entry_bytes),
        );
        consider(17, self.type3_geometry_cache.oldest_entry_bytes());
        consider(18, self.type3_charproc_cache.oldest_entry_bytes());
        consider(19, self.type3_retained_charproc_cache.oldest_entry_bytes());

        match candidate.map(|(kind, _)| kind) {
            Some(0) => {
                let evicted = pop_front_font_bytes_cache_entry(
                    &mut self.font_bytes_cache,
                    &mut self.font_bytes_cache_order,
                    &mut self.font_bytes_cache_bytes,
                );
                if evicted {
                    self.font_bytes_cache_stats.evictions =
                        self.font_bytes_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(1) => {
                let evicted = pop_front_ordered_cache_entry(
                    &mut self.font_resolver_cache,
                    &mut self.font_resolver_cache_order,
                    &mut self.font_resolver_cache_bytes,
                    |_| font_resolver_cache_entry_bytes(),
                );
                if evicted {
                    self.font_resolver_cache_stats.evictions =
                        self.font_resolver_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(2) => self.glyph_cache.evict_one_lru(),
            Some(3) => {
                let evicted = self.glyph_mask_cache.evict_one();
                if evicted {
                    self.glyph_mask_cache.stats.evictions =
                        self.glyph_mask_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(4) => {
                let evicted = self.type3_mask_cache.evict_one();
                if evicted {
                    self.type3_mask_cache.stats.evictions =
                        self.type3_mask_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(5) => {
                let evicted = self.type3_rendered_cache.evict_one();
                if evicted {
                    self.type3_rendered_cache.stats.evictions =
                        self.type3_rendered_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(6) => {
                let evicted = self.path_fill_mask_cache.evict_one();
                if evicted {
                    self.path_fill_mask_cache.stats.evictions =
                        self.path_fill_mask_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(7) => {
                let evicted = self.path_stroke_mask_cache.evict_one();
                if evicted {
                    self.path_stroke_mask_cache.stats.evictions = self
                        .path_stroke_mask_cache
                        .stats
                        .evictions
                        .saturating_add(1);
                }
                evicted
            }
            Some(8) => {
                let evicted = pop_front_display_list_cache_entry(
                    &mut self.display_list_cache,
                    &mut self.display_list_cache_order,
                    &mut self.display_list_cache_bytes,
                );
                if evicted {
                    self.display_list_cache_stats.evictions =
                        self.display_list_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(9) => {
                let evicted = self.path_clip_node_cache.evict_one();
                if evicted {
                    self.path_clip_node_cache.stats.evictions =
                        self.path_clip_node_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(10) => {
                let evicted = pop_front_image_xobject_cache_entry(
                    &mut self.image_xobject_cache,
                    &mut self.image_xobject_cache_order,
                    &mut self.image_xobject_cache_bytes,
                );
                if evicted {
                    self.image_xobject_cache_stats.evictions =
                        self.image_xobject_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(11) => {
                let evicted = pop_front_scaled_image_cache_entry(
                    &mut self.scaled_image_cache,
                    &mut self.scaled_image_cache_order,
                    &mut self.scaled_image_cache_bytes,
                );
                if evicted {
                    self.scaled_image_cache_stats.evictions =
                        self.scaled_image_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(12) => {
                let evicted = pop_front_smask_group_cache_entry(
                    &mut self.smask_group_cache,
                    &mut self.smask_group_cache_order,
                    &mut self.smask_group_cache_bytes,
                );
                if evicted {
                    self.smask_group_cache_stats.evictions =
                        self.smask_group_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(13) => {
                let evicted = pop_front_shading_mesh_cache_entry(
                    &mut self.shading_mesh_cache,
                    &mut self.shading_mesh_cache_order,
                    &mut self.shading_mesh_cache_bytes,
                );
                if evicted {
                    self.shading_mesh_cache_stats.evictions =
                        self.shading_mesh_cache_stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(14) => {
                let evicted = pop_front_program_cache_entry(
                    &mut self.form_xobject_program_cache,
                    &mut self.form_xobject_program_cache_order,
                    &mut self.form_xobject_program_cache_bytes,
                    form_xobject_program_cache_entry_bytes,
                );
                if evicted {
                    self.form_xobject_program_cache_stats.evictions = self
                        .form_xobject_program_cache_stats
                        .evictions
                        .saturating_add(1);
                }
                evicted
            }
            Some(15) => {
                let evicted = pop_front_program_cache_entry(
                    &mut self.tiling_pattern_program_cache,
                    &mut self.tiling_pattern_program_cache_order,
                    &mut self.tiling_pattern_program_cache_bytes,
                    tiling_pattern_program_cache_entry_bytes,
                );
                if evicted {
                    self.tiling_pattern_program_cache_stats.evictions = self
                        .tiling_pattern_program_cache_stats
                        .evictions
                        .saturating_add(1);
                }
                evicted
            }
            Some(16) => {
                let evicted = pop_front_program_cache_entry(
                    &mut self.annotation_appearance_program_cache,
                    &mut self.annotation_appearance_program_cache_order,
                    &mut self.annotation_appearance_program_cache_bytes,
                    form_xobject_program_cache_entry_bytes,
                );
                if evicted {
                    self.annotation_appearance_program_cache_stats.evictions = self
                        .annotation_appearance_program_cache_stats
                        .evictions
                        .saturating_add(1);
                }
                evicted
            }
            Some(17) => {
                let evicted = self.type3_geometry_cache.evict_one_lru();
                if evicted {
                    self.type3_geometry_cache.stats.evictions =
                        self.type3_geometry_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(18) => {
                let evicted = self.type3_charproc_cache.evict_one_lru();
                if evicted {
                    self.type3_charproc_cache.stats.evictions =
                        self.type3_charproc_cache.stats.evictions.saturating_add(1);
                }
                evicted
            }
            Some(19) => {
                let evicted = self.type3_retained_charproc_cache.evict_one_lru();
                if evicted {
                    self.type3_retained_charproc_cache.stats.evictions = self
                        .type3_retained_charproc_cache
                        .stats
                        .evictions
                        .saturating_add(1);
                }
                evicted
            }
            _ => false,
        }
    }

    pub fn bind_document_revision(&mut self, revision: RevisionId) {
        if self.document_revision == Some(revision) {
            return;
        }
        self.reset_to_revision(revision);
    }

    pub fn reset_to_revision(&mut self, revision: RevisionId) {
        self.clear();
        self.document_revision = Some(revision);
        self.dependency_graph = Some(RenderDependencyGraph::new(revision));
    }

    pub fn reset_to_revision_with_result(&mut self, revision: RevisionId) -> InvalidationResult {
        let previous_revision = self.document_revision.unwrap_or_default();
        self.reset_to_revision(revision);
        InvalidationResult {
            previous_revision,
            current_revision: revision,
            invalidated_pages: Vec::new(),
            invalidated_tiles: Vec::new(),
            cache_must_reset: true,
        }
    }

    pub fn document_revision(&self) -> Option<RevisionId> {
        self.document_revision
    }

    pub fn remember_source_identities(&mut self, identities: &[ObjectIdentity]) {
        for identity in identities {
            self.source_identities
                .insert((identity.number, identity.generation), identity.id);
            self.source_cache_markers.insert(
                identity.id,
                source_cache_markers_for_object(identity.number, identity.generation),
            );
        }
    }

    pub(crate) fn source_identity_for_object(
        &self,
        number: u32,
        generation: u16,
    ) -> Option<ObjectIdentityId> {
        self.source_identities.get(&(number, generation)).copied()
    }

    pub(crate) fn remember_source_cache_markers(
        &mut self,
        source: ObjectIdentityId,
        markers: Vec<String>,
    ) {
        let entry = self.source_cache_markers.entry(source).or_default();
        entry.extend(markers);
        entry.sort();
        entry.dedup();
    }

    pub fn record_page_source_dependency(&mut self, page_number: usize, source: ObjectIdentityId) {
        if let Some(graph) = &mut self.dependency_graph {
            graph.record_page_source(page_number, source);
        }
    }

    pub fn record_tile_dependency(&mut self, page_number: usize, tile: RenderTile) {
        if let Some(graph) = &mut self.dependency_graph {
            graph.record_tile(page_number, tile);
        }
    }

    pub fn record_tile_source_dependency(
        &mut self,
        page_number: usize,
        source: ObjectIdentityId,
        tile: RenderTile,
    ) {
        if let Some(graph) = &mut self.dependency_graph {
            graph.record_source_tile(page_number, source, tile);
        }
    }

    pub fn record_source_dependency(
        &mut self,
        dependent_source: ObjectIdentityId,
        dependency_source: ObjectIdentityId,
    ) {
        if let Some(graph) = &mut self.dependency_graph {
            graph.record_source_dependency(dependent_source, dependency_source);
        }
    }

    fn invalidate_page_artifacts(&mut self, pages: &[usize]) {
        self.invalidate_page_artifacts_impl(pages, true);
    }

    fn invalidate_page_structural_artifacts(&mut self, pages: &[usize]) {
        self.invalidate_page_artifacts_impl(pages, false);
    }

    fn invalidate_page_artifacts_impl(&mut self, pages: &[usize], include_page_rasters: bool) {
        for page in pages {
            let prefix = format!("page:{page}:");
            remove_ordered_cache_entries_matching(
                &mut self.display_list_cache,
                &mut self.display_list_cache_order,
                &mut self.display_list_cache_bytes,
                &mut self.display_list_cache_stats,
                &[prefix],
                display_list_cache_entry_bytes,
            );
        }
        let removed_transparent_keys = self
            .transparent_page_group_cache
            .keys()
            .filter(|key| {
                pages
                    .iter()
                    .any(|page| key.starts_with(&format!("page:{page}:")))
            })
            .cloned()
            .collect::<HashSet<_>>();
        if !removed_transparent_keys.is_empty() {
            for key in &removed_transparent_keys {
                self.transparent_page_group_cache.remove(key);
            }
            self.transparent_page_group_cache_order
                .retain(|key| !removed_transparent_keys.contains(key));
        }
        if include_page_rasters {
            self.display_list_raster_cache.invalidate_pages(pages);
        }
        self.prune_page_scoped_artifact_caches(pages);
    }

    fn invalidate_tile_raster_artifacts(&mut self, page_tiles: &[(usize, RenderTile)]) {
        self.display_list_raster_cache.invalidate_tiles(page_tiles);
    }

    pub(crate) fn source_cache_markers_for_changed_sources(
        &self,
        changed_sources: &[ObjectIdentityId],
    ) -> Vec<String> {
        let mut markers = Vec::new();
        for source in changed_sources {
            if let Some(source_markers) = self.source_cache_markers.get(source) {
                markers.extend(source_markers.iter().cloned());
            }
        }
        markers.sort();
        markers.dedup();
        markers
    }

    fn prune_source_scoped_artifact_caches(&mut self, changed_sources: &[ObjectIdentityId]) {
        let markers = self.source_cache_markers_for_changed_sources(changed_sources);
        if markers.is_empty() {
            return;
        }
        remove_ordered_cache_entries_matching(
            &mut self.font_bytes_cache,
            &mut self.font_bytes_cache_order,
            &mut self.font_bytes_cache_bytes,
            &mut self.font_bytes_cache_stats,
            &markers,
            font_bytes_cache_entry_bytes,
        );
        remove_ordered_cache_entries_matching(
            &mut self.font_resolver_cache,
            &mut self.font_resolver_cache_order,
            &mut self.font_resolver_cache_bytes,
            &mut self.font_resolver_cache_stats,
            &markers,
            |_| font_resolver_cache_entry_bytes(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.image_xobject_cache,
            &mut self.image_xobject_cache_order,
            &mut self.image_xobject_cache_bytes,
            &mut self.image_xobject_cache_stats,
            &markers,
            |raw| raw.byte_count(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.scaled_image_cache,
            &mut self.scaled_image_cache_order,
            &mut self.scaled_image_cache_bytes,
            &mut self.scaled_image_cache_stats,
            &markers,
            |raw| raw.byte_count(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.smask_group_cache,
            &mut self.smask_group_cache_order,
            &mut self.smask_group_cache_bytes,
            &mut self.smask_group_cache_stats,
            &markers,
            |mask| mask.approximate_bytes(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.shading_mesh_cache,
            &mut self.shading_mesh_cache_order,
            &mut self.shading_mesh_cache_bytes,
            &mut self.shading_mesh_cache_stats,
            &markers,
            |bytes| bytes.len(),
        );
        remove_unordered_cache_entries_matching(
            &mut self.form_xobject_program_cache,
            &mut self.form_xobject_program_cache_order,
            &mut self.form_xobject_program_cache_bytes,
            &mut self.form_xobject_program_cache_stats,
            &markers,
            form_xobject_program_cache_entry_bytes,
        );
        remove_unordered_cache_entries_matching(
            &mut self.tiling_pattern_program_cache,
            &mut self.tiling_pattern_program_cache_order,
            &mut self.tiling_pattern_program_cache_bytes,
            &mut self.tiling_pattern_program_cache_stats,
            &markers,
            tiling_pattern_program_cache_entry_bytes,
        );
        remove_unordered_cache_entries_matching(
            &mut self.annotation_appearance_program_cache,
            &mut self.annotation_appearance_program_cache_order,
            &mut self.annotation_appearance_program_cache_bytes,
            &mut self.annotation_appearance_program_cache_stats,
            &markers,
            form_xobject_program_cache_entry_bytes,
        );
        self.type3_mask_cache.remove_entries_matching(&markers);
        self.type3_rendered_cache.remove_entries_matching(&markers);
        self.type3_geometry_cache.remove_entries_matching(&markers);
        self.type3_charproc_cache.remove_entries_matching(&markers);
        self.type3_retained_charproc_cache
            .remove_entries_matching(&markers);
    }

    fn prune_page_scoped_artifact_caches(&mut self, pages: &[usize]) {
        if pages.is_empty() {
            return;
        }
        let markers = pages
            .iter()
            .map(|page| format!(":page:{page}:"))
            .collect::<Vec<_>>();
        remove_ordered_cache_entries_matching(
            &mut self.image_xobject_cache,
            &mut self.image_xobject_cache_order,
            &mut self.image_xobject_cache_bytes,
            &mut self.image_xobject_cache_stats,
            &markers,
            |raw| raw.byte_count(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.scaled_image_cache,
            &mut self.scaled_image_cache_order,
            &mut self.scaled_image_cache_bytes,
            &mut self.scaled_image_cache_stats,
            &markers,
            |raw| raw.byte_count(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.smask_group_cache,
            &mut self.smask_group_cache_order,
            &mut self.smask_group_cache_bytes,
            &mut self.smask_group_cache_stats,
            &markers,
            |mask| mask.approximate_bytes(),
        );
        remove_ordered_cache_entries_matching(
            &mut self.shading_mesh_cache,
            &mut self.shading_mesh_cache_order,
            &mut self.shading_mesh_cache_bytes,
            &mut self.shading_mesh_cache_stats,
            &markers,
            |bytes| bytes.len(),
        );
        remove_unordered_cache_entries_matching(
            &mut self.form_xobject_program_cache,
            &mut self.form_xobject_program_cache_order,
            &mut self.form_xobject_program_cache_bytes,
            &mut self.form_xobject_program_cache_stats,
            &markers,
            form_xobject_program_cache_entry_bytes,
        );
        remove_unordered_cache_entries_matching(
            &mut self.tiling_pattern_program_cache,
            &mut self.tiling_pattern_program_cache_order,
            &mut self.tiling_pattern_program_cache_bytes,
            &mut self.tiling_pattern_program_cache_stats,
            &markers,
            tiling_pattern_program_cache_entry_bytes,
        );
        remove_unordered_cache_entries_matching(
            &mut self.annotation_appearance_program_cache,
            &mut self.annotation_appearance_program_cache_order,
            &mut self.annotation_appearance_program_cache_bytes,
            &mut self.annotation_appearance_program_cache_stats,
            &markers,
            form_xobject_program_cache_entry_bytes,
        );
        self.type3_retained_charproc_cache
            .remove_entries_matching(&markers);
    }

    pub fn invalidate_sources(
        &mut self,
        next_revision: RevisionId,
        changed_sources: &[ObjectIdentityId],
    ) -> InvalidationResult {
        self.invalidate_sources_and_pages(next_revision, changed_sources, &[])
    }

    pub fn invalidate_sources_and_pages(
        &mut self,
        next_revision: RevisionId,
        changed_sources: &[ObjectIdentityId],
        affected_pages: &[usize],
    ) -> InvalidationResult {
        self.invalidate_sources_pages_and_tiles(next_revision, changed_sources, affected_pages, &[])
    }

    pub fn invalidate_sources_pages_and_tiles(
        &mut self,
        next_revision: RevisionId,
        changed_sources: &[ObjectIdentityId],
        affected_pages: &[usize],
        affected_tiles: &[(usize, RenderTile)],
    ) -> InvalidationResult {
        let mut graph = self.dependency_graph.take().unwrap_or_else(|| {
            RenderDependencyGraph::new(self.document_revision.unwrap_or(next_revision))
        });
        let cache_prune_sources = graph.expand_changed_sources(changed_sources);
        let result = graph.invalidate_sources_pages_and_tiles(
            next_revision,
            changed_sources,
            affected_pages,
            affected_tiles,
        );
        if result.cache_must_reset {
            self.clear();
            self.document_revision = Some(next_revision);
            self.dependency_graph = Some(RenderDependencyGraph::new(next_revision));
        } else {
            self.prune_source_scoped_artifact_caches(&cache_prune_sources);
            self.invalidate_page_artifacts(&result.invalidated_pages);
            self.invalidate_tile_raster_artifacts(&result.invalidated_tiles);
            self.document_revision = Some(next_revision);
            graph.advance_revision(next_revision);
            self.dependency_graph = Some(graph);
        }
        result
    }

    pub fn invalidate_sources_page_artifacts_and_exact_tiles(
        &mut self,
        next_revision: RevisionId,
        changed_sources: &[ObjectIdentityId],
        affected_pages: &[usize],
        affected_tiles: &[(usize, RenderTile)],
    ) -> InvalidationResult {
        let mut graph = self.dependency_graph.take().unwrap_or_else(|| {
            RenderDependencyGraph::new(self.document_revision.unwrap_or(next_revision))
        });
        let cache_prune_sources = graph.expand_changed_sources(changed_sources);
        let result = graph.invalidate_sources_page_artifacts_and_exact_tiles(
            next_revision,
            changed_sources,
            affected_pages,
            affected_tiles,
        );
        if result.cache_must_reset {
            self.clear();
            self.document_revision = Some(next_revision);
            self.dependency_graph = Some(RenderDependencyGraph::new(next_revision));
        } else {
            self.prune_source_scoped_artifact_caches(&cache_prune_sources);
            self.invalidate_page_structural_artifacts(&result.invalidated_pages);
            self.invalidate_tile_raster_artifacts(&result.invalidated_tiles);
            self.document_revision = Some(next_revision);
            graph.advance_revision(next_revision);
            self.dependency_graph = Some(graph);
        }
        result
    }

