const RENDER_DOCUMENT_IMAGE_CACHE_MAX_BYTES: usize = 512 * 1024 * 1024;
const TRANSPARENT_PAGE_GROUP_CACHE_ENTRIES: usize = 512;

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
struct GlyphMaskCacheKey {
    glyph: GlyphCacheKey,
    a: i64,
    b: i64,
    c: i64,
    d: i64,
    frac_e: i64,
    frac_f: i64,
    hinting: bool,
    binary_alpha: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GlyphAtlasPlacement {
    page_id: u64,
    atlas_x: u32,
    atlas_y: u32,
    width: u32,
    height: u32,
    mask_x: i32,
    mask_y: i32,
}

#[derive(Clone)]
struct GlyphMaskCacheEntry {
    mask: Arc<RasterizedGlyphMask>,
    atlas: Option<GlyphAtlasPlacement>,
}

impl GlyphMaskCacheEntry {
    fn approximate_bytes(&self) -> usize {
        std::mem::size_of::<Self>().saturating_add(self.mask.approximate_bytes())
    }
}

struct GlyphAtlasPage {
    id: u64,
    width: u32,
    height: u32,
    alpha: Vec<u8>,
    cursor_x: u32,
    cursor_y: u32,
    row_height: u32,
    live_entries: usize,
}

impl GlyphAtlasPage {
    const EDGE: u32 = 1024;

    fn new(id: u64) -> Self {
        Self {
            id,
            width: Self::EDGE,
            height: Self::EDGE,
            alpha: vec![0u8; Self::EDGE as usize * Self::EDGE as usize],
            cursor_x: 0,
            cursor_y: 0,
            row_height: 0,
            live_entries: 0,
        }
    }

    fn approximate_bytes(&self) -> usize {
        std::mem::size_of::<Self>().saturating_add(self.alpha.len())
    }

    fn try_place(&mut self, mask: &RasterizedGlyphMask) -> Option<GlyphAtlasPlacement> {
        if mask.width == 0
            || mask.height == 0
            || mask.width > self.width
            || mask.height > self.height
        {
            return None;
        }

        if self.cursor_x.saturating_add(mask.width) > self.width {
            self.cursor_x = 0;
            self.cursor_y = self.cursor_y.saturating_add(self.row_height);
            self.row_height = 0;
        }
        if self.cursor_y.saturating_add(mask.height) > self.height {
            return None;
        }

        let atlas_x = self.cursor_x;
        let atlas_y = self.cursor_y;
        let stride = self.width as usize;
        let mask_width = mask.width as usize;
        for row in 0..mask.height as usize {
            let dst_start = (atlas_y as usize + row)
                .saturating_mul(stride)
                .saturating_add(atlas_x as usize);
            let src_start = row.saturating_mul(mask_width);
            let dst = self
                .alpha
                .get_mut(dst_start..dst_start.saturating_add(mask_width))?;
            let src = mask
                .alpha_slice()
                .get(src_start..src_start.saturating_add(mask_width))?;
            dst.copy_from_slice(src);
        }

        self.cursor_x = self.cursor_x.saturating_add(mask.width);
        self.row_height = self.row_height.max(mask.height);
        self.live_entries = self.live_entries.saturating_add(1);
        Some(GlyphAtlasPlacement {
            page_id: self.id,
            atlas_x,
            atlas_y,
            width: mask.width,
            height: mask.height,
            mask_x: mask.x,
            mask_y: mask.y,
        })
    }
}

#[derive(Default)]
struct GlyphMaskAtlas {
    pages: HashMap<u64, GlyphAtlasPage>,
    order: VecDeque<u64>,
    next_page_id: u64,
    placements: usize,
    bytes: usize,
    stats: RenderArtifactCacheStats,
}

impl GlyphMaskAtlas {
    const MAX_MASK_EDGE: u32 = 256;

    fn try_insert(
        &mut self,
        mask: &RasterizedGlyphMask,
        max_extra_bytes: usize,
    ) -> Option<GlyphAtlasPlacement> {
        if mask.width == 0
            || mask.height == 0
            || mask.width > Self::MAX_MASK_EDGE
            || mask.height > Self::MAX_MASK_EDGE
        {
            self.stats.skipped_oversized = self.stats.skipped_oversized.saturating_add(1);
            return None;
        }

        let page_ids: Vec<_> = self.order.iter().copied().rev().collect();
        for page_id in page_ids {
            if let Some(page) = self.pages.get_mut(&page_id) {
                if let Some(placement) = page.try_place(mask) {
                    self.placements = self.placements.saturating_add(1);
                    return Some(placement);
                }
            }
        }

        let new_page = GlyphAtlasPage::new(self.next_page_id);
        let new_page_bytes = new_page.approximate_bytes();
        if new_page_bytes > max_extra_bytes {
            self.stats.skipped_oversized = self.stats.skipped_oversized.saturating_add(1);
            return None;
        }
        let page_id = new_page.id;
        self.next_page_id = self.next_page_id.saturating_add(1);
        self.bytes = self.bytes.saturating_add(new_page_bytes);
        self.order.push_back(page_id);
        self.pages.insert(page_id, new_page);

        let page = self
            .pages
            .get_mut(&page_id)
            .expect("newly inserted atlas page exists");
        let placement = page.try_place(mask)?;
        self.placements = self.placements.saturating_add(1);
        Some(placement)
    }

    fn paint(
        &mut self,
        placement: &GlyphAtlasPlacement,
        buf: &mut PixelBuffer,
        dx: i32,
        dy: i32,
        color: PixelColor,
        subpixel_rgb: bool,
    ) -> bool {
        let Some(page) = self.pages.get(&placement.page_id) else {
            self.stats.misses = self.stats.misses.saturating_add(1);
            return false;
        };
        let Some(offset) = (placement.atlas_y as usize)
            .checked_mul(page.width as usize)
            .and_then(|row| row.checked_add(placement.atlas_x as usize))
        else {
            self.stats.misses = self.stats.misses.saturating_add(1);
            return false;
        };
        self.stats.hits = self.stats.hits.saturating_add(1);
        if subpixel_rgb {
            buf.blend_lcd_alpha_mask_strided(
                dx.saturating_add(placement.mask_x),
                dy.saturating_add(placement.mask_y),
                placement.width,
                placement.height,
                &page.alpha,
                page.width as usize,
                offset,
                color,
            );
        } else {
            buf.blend_alpha_mask_strided(
                dx.saturating_add(placement.mask_x),
                dy.saturating_add(placement.mask_y),
                placement.width,
                placement.height,
                &page.alpha,
                page.width as usize,
                offset,
                color,
            );
        }
        true
    }

    fn remove_placement(&mut self, placement: &GlyphAtlasPlacement) {
        let Some(page) = self.pages.get_mut(&placement.page_id) else {
            return;
        };
        page.live_entries = page.live_entries.saturating_sub(1);
        self.placements = self.placements.saturating_sub(1);
        if page.live_entries == 0 {
            if let Some(removed) = self.pages.remove(&placement.page_id) {
                self.bytes = self.bytes.saturating_sub(removed.approximate_bytes());
                self.order.retain(|page_id| *page_id != placement.page_id);
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            }
        }
    }

    fn clear(&mut self) {
        self.pages.clear();
        self.order.clear();
        self.placements = 0;
        self.bytes = 0;
        self.stats = RenderArtifactCacheStats::default();
    }

    fn bytes(&self) -> usize {
        self.bytes
    }

    fn stats(&self) -> RenderArtifactCacheStats {
        RenderArtifactCacheStats {
            entries: self.placements,
            bytes: self.bytes,
            ..self.stats
        }
    }
}

#[derive(Default)]
struct GlyphMaskCache {
    entries: HashMap<GlyphMaskCacheKey, GlyphMaskCacheEntry>,
    order: VecDeque<GlyphMaskCacheKey>,
    bytes: usize,
    atlas: GlyphMaskAtlas,
    stats: RenderArtifactCacheStats,
}

impl GlyphMaskCache {
    const MAX_ENTRIES: usize = 4096;
    const MAX_BYTES: usize = 32 * 1024 * 1024;

    #[cfg(test)]
    fn get(&mut self, key: &GlyphMaskCacheKey) -> Option<Arc<RasterizedGlyphMask>> {
        let hit = self.entries.get(key).map(|entry| entry.mask.clone());
        if hit.is_some() {
            self.stats.hits = self.stats.hits.saturating_add(1);
            self.touch(key);
        } else {
            self.stats.misses = self.stats.misses.saturating_add(1);
        }
        hit
    }

    fn len(&self) -> usize {
        self.entries.len()
    }

    fn bytes(&self) -> usize {
        self.bytes.saturating_add(self.atlas.bytes())
    }

    fn clear(&mut self) {
        self.entries.clear();
        self.order.clear();
        self.bytes = 0;
        self.atlas.clear();
        self.stats = RenderArtifactCacheStats::default();
    }

    fn stats(&self) -> RenderArtifactCacheStats {
        RenderArtifactCacheStats {
            entries: self.entries.len(),
            bytes: self.bytes(),
            ..self.stats
        }
    }

    fn atlas_stats(&self) -> RenderArtifactCacheStats {
        self.atlas.stats()
    }

    fn oldest_entry_bytes(&self) -> Option<usize> {
        self.order
            .front()
            .and_then(|key| self.entries.get(key))
            .map(GlyphMaskCacheEntry::approximate_bytes)
    }

    fn paint(
        &mut self,
        key: &GlyphMaskCacheKey,
        buf: &mut PixelBuffer,
        dx: i32,
        dy: i32,
        color: PixelColor,
        subpixel_rgb: bool,
    ) -> bool {
        let Some(entry) = self.entries.get(key).cloned() else {
            self.stats.misses = self.stats.misses.saturating_add(1);
            return false;
        };
        self.stats.hits = self.stats.hits.saturating_add(1);
        self.touch(key);
        if let Some(placement) = entry.atlas.as_ref() {
            if self
                .atlas
                .paint(placement, buf, dx, dy, color, subpixel_rgb)
            {
                return true;
            }
        }
        if subpixel_rgb {
            entry.mask.paint_subpixel_rgb(buf, dx, dy, color);
        } else {
            entry.mask.paint(buf, dx, dy, color);
        }
        true
    }

    fn insert(&mut self, key: GlyphMaskCacheKey, mask: Arc<RasterizedGlyphMask>) {
        let bytes = mask.approximate_bytes();
        if bytes > Self::MAX_BYTES / 4 {
            self.stats.skipped_oversized = self.stats.skipped_oversized.saturating_add(1);
            return;
        }
        if let Some(old) = self.entries.remove(&key) {
            self.bytes = self.bytes.saturating_sub(old.approximate_bytes());
            if let Some(placement) = old.atlas.as_ref() {
                self.atlas.remove_placement(placement);
            }
            self.remove_ordered(&key);
        }
        while self.entries.len() >= Self::MAX_ENTRIES
            || self.bytes().saturating_add(bytes) > Self::MAX_BYTES
        {
            if self.evict_one() {
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
        if self.entries.len() < Self::MAX_ENTRIES
            && self.bytes().saturating_add(bytes) <= Self::MAX_BYTES
        {
            let atlas_extra_budget = Self::MAX_BYTES
                .saturating_sub(self.bytes())
                .saturating_sub(bytes);
            let atlas = self.atlas.try_insert(&mask, atlas_extra_budget);
            let entry = GlyphMaskCacheEntry { mask, atlas };
            let entry_bytes = entry.approximate_bytes();
            self.order.push_back(key.clone());
            self.bytes = self.bytes.saturating_add(entry_bytes);
            self.entries.insert(key, entry);
        }
    }

    fn absorb_from(&mut self, mut other: Self) {
        merge_artifact_cache_counts(&mut self.stats, other.stats());
        merge_artifact_cache_counts(&mut self.atlas.stats, other.atlas.stats());
        for key in std::mem::take(&mut other.order) {
            if let Some(entry) = other.entries.remove(&key) {
                self.insert(key, entry.mask);
            }
        }
        for (key, entry) in other.entries {
            self.insert(key, entry.mask);
        }
    }

    fn touch(&mut self, key: &GlyphMaskCacheKey) {
        self.remove_ordered(key);
        self.order.push_back(key.clone());
    }

    fn remove_ordered(&mut self, key: &GlyphMaskCacheKey) {
        if let Some(pos) = self.order.iter().position(|item| item == key) {
            self.order.remove(pos);
        }
    }

    fn evict_one(&mut self) -> bool {
        while let Some(victim) = self.order.pop_front() {
            if let Some(removed) = self.entries.remove(&victim) {
                self.bytes = self.bytes.saturating_sub(removed.approximate_bytes());
                if let Some(placement) = removed.atlas.as_ref() {
                    self.atlas.remove_placement(placement);
                }
                return true;
            }
        }
        false
    }
}

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
struct Type3MaskCacheKey {
    glyph: String,
    fill_index: u16,
    fill_rule: u8,
    a: i64,
    b: i64,
    c: i64,
    d: i64,
    frac_e: i64,
    frac_f: i64,
    binary_alpha: bool,
}

#[derive(Default)]
struct Type3MaskCache {
    entries: HashMap<Type3MaskCacheKey, Arc<RasterizedGlyphMask>>,
    order: VecDeque<Type3MaskCacheKey>,
    bytes: usize,
    stats: RenderArtifactCacheStats,
}

impl Type3MaskCache {
    const MAX_ENTRIES: usize = 8192;
    const MAX_BYTES: usize = 64 * 1024 * 1024;

    fn get(&mut self, key: &Type3MaskCacheKey) -> Option<Arc<RasterizedGlyphMask>> {
        let hit = self.entries.get(key).cloned();
        if hit.is_some() {
            self.stats.hits = self.stats.hits.saturating_add(1);
            self.touch(key);
        } else {
            self.stats.misses = self.stats.misses.saturating_add(1);
        }
        hit
    }

    fn len(&self) -> usize {
        self.entries.len()
    }

    fn bytes(&self) -> usize {
        self.bytes
    }

    fn clear(&mut self) {
        self.entries.clear();
        self.order.clear();
        self.bytes = 0;
        self.stats = RenderArtifactCacheStats::default();
    }

    fn stats(&self) -> RenderArtifactCacheStats {
        RenderArtifactCacheStats {
            entries: self.entries.len(),
            bytes: self.bytes,
            ..self.stats
        }
    }

    fn oldest_entry_bytes(&self) -> Option<usize> {
        self.order
            .front()
            .and_then(|key| self.entries.get(key))
            .map(|mask| mask.approximate_bytes())
    }

    fn insert(&mut self, key: Type3MaskCacheKey, mask: Arc<RasterizedGlyphMask>) {
        let bytes = mask.approximate_bytes();
        if bytes > Self::MAX_BYTES / 4 {
            self.stats.skipped_oversized = self.stats.skipped_oversized.saturating_add(1);
            return;
        }
        if let Some(old) = self.entries.remove(&key) {
            self.bytes = self.bytes.saturating_sub(old.approximate_bytes());
            self.remove_ordered(&key);
        }
        while self.entries.len() >= Self::MAX_ENTRIES
            || self.bytes.saturating_add(bytes) > Self::MAX_BYTES
        {
            if self.evict_one() {
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            } else {
                break;
            }
        }
        if self.entries.len() < Self::MAX_ENTRIES
            && self.bytes.saturating_add(bytes) <= Self::MAX_BYTES
        {
            self.order.push_back(key.clone());
            self.bytes = self.bytes.saturating_add(bytes);
            self.entries.insert(key, mask);
        }
    }

    fn touch(&mut self, key: &Type3MaskCacheKey) {
        self.remove_ordered(key);
        self.order.push_back(key.clone());
    }

    fn remove_ordered(&mut self, key: &Type3MaskCacheKey) {
        if let Some(pos) = self.order.iter().position(|item| item == key) {
            self.order.remove(pos);
        }
    }

    fn evict_one(&mut self) -> bool {
        while let Some(victim) = self.order.pop_front() {
            if let Some(removed) = self.entries.remove(&victim) {
                self.bytes = self.bytes.saturating_sub(removed.approximate_bytes());
                return true;
            }
        }
        false
    }

    fn remove_entries_matching(&mut self, markers: &[String]) {
        let removed_keys = self
            .entries
            .keys()
            .filter(|key| cache_key_matches_page_marker(&key.glyph, markers))
            .cloned()
            .collect::<HashSet<_>>();
        if removed_keys.is_empty() {
            return;
        }

        let mut removed_count = 0u64;
        for key in &removed_keys {
            if let Some(removed) = self.entries.remove(key) {
                self.bytes = self.bytes.saturating_sub(removed.approximate_bytes());
                removed_count = removed_count.saturating_add(1);
            }
        }
        self.order.retain(|key| !removed_keys.contains(key));
        self.stats.evictions = self.stats.evictions.saturating_add(removed_count);
    }
}

