    #[allow(clippy::too_many_arguments)]
    fn scheduled_decode_inline_raw_window_with_color_space(
        &self,
        data: &[u8],
        width: u32,
        height: u32,
        bpc: u8,
        color_space: &str,
        filters: &[&str],
        decode_params: &[Option<PdfDictionary>],
        window: RawImageDecodeWindow,
        component_selection: RawImageComponentSelection,
        color_space_override: Option<&(String, PdfObject)>,
    ) -> Result<RawImage> {
        let estimated = u64::from(window.width)
            .saturating_mul(u64::from(window.height))
            .saturating_mul(u64::from(bpc.max(1)))
            .saturating_div(8)
            .saturating_mul(estimated_component_selection_channels(
                color_space,
                false,
                &component_selection,
            ))
            .max(1);
        let limits = self.decode_limits.clone();
        let color_options = self.color_transform_options();
        self.decode_scheduler.run(
            estimated,
            &self.cancel,
            "renderer inline raw window decode",
            || {
                let color_space_obj = color_space_override.map(|(_, object)| object);
                match component_selection {
                    RawImageComponentSelection::All => {
                        ImageDecoder::decode_inline_raw_window_with_resolved_color_space_and_param_array(
                            data,
                            width,
                            height,
                            bpc,
                            color_space,
                            color_space_obj,
                            filters,
                            decode_params,
                            window,
                            &limits,
                            Some(self.engine.document().reader()),
                            color_options,
                        )
                    }
                    selection => ImageDecoder::decode_inline_raw_window_components_with_resolved_color_space_and_param_array(
                        data,
                        width,
                        height,
                        bpc,
                        color_space,
                        color_space_obj,
                        filters,
                        decode_params,
                        window,
                        selection,
                        &limits,
                        Some(self.engine.document().reader()),
                        color_options,
                    ),
                }
            },
        )
    }

