    fn scheduled_load_smask(
        &self,
        image_ref: &ImageReference,
        raw: RawImage,
        source_region: ImageSourceRegion,
    ) -> Result<Option<RawImage>> {
        let source_window = raw_window_from_source_region(source_region);
        let estimated_width = source_window
            .map(|window| window.width)
            .unwrap_or(image_ref.width);
        let estimated_height = source_window
            .map(|window| window.height)
            .unwrap_or(image_ref.height);
        let estimated = u64::from(estimated_width)
            .saturating_mul(u64::from(estimated_height))
            .saturating_mul(2)
            .max(raw.byte_count() as u64)
            .max(1);
        let limits = self.decode_limits.clone();
        self.decode_scheduler.run(
            estimated,
            &self.cancel,
            "renderer soft mask image decode",
            || {
                SmaskLoader::load_and_combine_with_limits_and_source_window(
                    image_ref,
                    raw,
                    self.engine.document().reader(),
                    &limits,
                    source_window,
                )
            },
        )
    }

    fn scheduled_load_explicit_image_mask(
        &mut self,
        image_ref: &ImageReference,
        image_dict: &PdfDictionary,
        raw: RawImage,
        source_region: ImageSourceRegion,
    ) -> Result<Option<RawImage>> {
        let Some(mask) = image_dict.get("Mask") else {
            return Ok(None);
        };
        match mask {
            PdfObject::Array(items) => {
                let raw_channels = raw.channels;
                apply_color_key_image_mask(
                    raw,
                    image_ref.bits_per_component,
                    &image_ref.color_space,
                    items,
                )
                .map(Some)
                .ok_or_else(|| {
                    WellfriendError::MalformedPdf(format!(
                        "image Mask color-key array is malformed or unsupported for {} image data ({} entries, {} bpc, {} channels)",
                        image_ref.color_space,
                        items.len(),
                        image_ref.bits_per_component,
                        raw_channels
                    ))
                })
            }
            PdfObject::Reference { number, generation } => {
                let reader = self.engine.document().reader();
                let mask_obj = reader.get_object(*number, *generation)?;
                let PdfObject::Stream {
                    dict: mask_dict, ..
                } = mask_obj
                else {
                    return Err(WellfriendError::MalformedPdf(format!(
                        "image Mask reference resolved to {}, expected Stream",
                        mask_obj.variant_name()
                    )));
                };
                let mask_ref =
                    explicit_image_mask_reference(image_ref, *number, *generation, &mask_dict)?;
                let mask_raw = if explicit_image_mask_supports_shared_raw_window(
                    image_ref, &mask_ref, image_dict,
                ) {
                    if let Some(window) = raw_window_from_source_region(source_region) {
                        let cache_key = explicit_mask_source_region_cache_key(
                            &self.image_decode_cache_base_key(&mask_ref, None),
                            source_region,
                        );
                        self.scheduled_decode_raw_window_with_cache_key(
                            &mask_ref,
                            None,
                            window,
                            RawImageComponentSelection::All,
                            &cache_key,
                            "renderer explicit image mask raw window decode",
                        )?
                    } else {
                        self.scheduled_decode_image(
                            &mask_ref,
                            "renderer explicit image mask decode",
                        )?
                    }
                } else {
                    self.scheduled_decode_image(&mask_ref, "renderer explicit image mask decode")?
                };
                let mask_paints_ones = if mask_ref.is_mask {
                    image_mask_paints_ones(&mask_dict)?
                } else {
                    true
                };
                combine_explicit_image_mask(
                    raw,
                    mask_raw.as_ref(),
                    mask_ref.is_mask,
                    mask_paints_ones,
                )
                .map(Some)
            }
            other => Err(WellfriendError::MalformedPdf(format!(
                "unsupported image Mask value {}",
                other.variant_name()
            ))),
        }
    }

    fn reserve_offscreen_surface(
        &self,
        width: u32,
        height: u32,
        context: &str,
    ) -> Result<DecodeMemoryToken> {
        self.temporary_scheduler.reserve_memory(
            estimate_rgba_surface_bytes(width, height),
            &self.cancel,
            context,
        )
    }

    fn take_transparent_offscreen_buffer(
        &mut self,
        width: u32,
        height: u32,
        render_mode: RenderMode,
    ) -> PixelBuffer {
        if let Some(index) = self
            .offscreen_buffer_pool
            .iter()
            .position(|buf| buf.width == width && buf.height == height)
        {
            let mut buf = self.offscreen_buffer_pool.swap_remove(index);
            if buf.reset_transparent_for_reuse(width, height, render_mode) {
                return buf;
            }
        }
        PixelBuffer::new_transparent_with_mode(width, height, render_mode)
    }

    fn take_filled_offscreen_buffer(
        &mut self,
        width: u32,
        height: u32,
        color: PixelColor,
        render_mode: RenderMode,
    ) -> PixelBuffer {
        if let Some(index) = self
            .offscreen_buffer_pool
            .iter()
            .position(|buf| buf.width == width && buf.height == height)
        {
            let mut buf = self.offscreen_buffer_pool.swap_remove(index);
            if buf.reset_filled_for_reuse(width, height, color, render_mode) {
                return buf;
            }
        }
        PixelBuffer::new_filled_with_mode(width, height, color, render_mode)
    }

    fn copy_current_window_to_offscreen_buffer(
        &mut self,
        x: u32,
        y: u32,
        width: u32,
        height: u32,
        render_mode: RenderMode,
    ) -> Option<PixelBuffer> {
        let mut out = self.take_transparent_offscreen_buffer(width, height, render_mode);
        if self.buf.copy_rect_into_buffer(x, y, &mut out) {
            Some(out)
        } else {
            self.recycle_offscreen_buffer(out);
            None
        }
    }

    fn recycle_offscreen_buffer(&mut self, mut buf: PixelBuffer) {
        const MAX_POOLED_BUFFERS: usize = 4;
        const MAX_POOLED_BYTES: usize = 64 * 1024 * 1024;
        let bytes = (buf.width as usize)
            .saturating_mul(buf.height as usize)
            .saturating_mul(4);
        if bytes == 0
            || bytes > self.cache_entry_budget(MAX_POOLED_BYTES)
            || self.offscreen_buffer_pool.len() >= MAX_POOLED_BUFFERS
        {
            return;
        }
        if !buf.reset_transparent_for_reuse(buf.width, buf.height, buf.render_mode()) {
            return;
        }
        self.offscreen_buffer_pool.push(buf);
    }

    fn absorb_child_render_caches(&mut self, child: &mut RenderState<'a>) {
        self.glyph_cache.absorb_from(std::mem::replace(
            &mut child.glyph_cache,
            GlyphCache::with_default_capacity(),
        ));

        self.glyph_mask_cache
            .absorb_from(std::mem::take(&mut child.glyph_mask_cache));

        merge_artifact_cache_counts(
            &mut self.type3_mask_cache.stats,
            child.type3_mask_cache.stats(),
        );
        for (key, mask) in std::mem::take(&mut child.type3_mask_cache.entries) {
            self.type3_mask_cache.insert(key, mask);
        }
        child.type3_mask_cache.bytes = 0;

        merge_artifact_cache_counts(
            &mut self.type3_rendered_cache.stats,
            child.type3_rendered_cache.stats(),
        );
        for (key, glyph) in std::mem::take(&mut child.type3_rendered_cache.entries) {
            self.type3_rendered_cache.insert(key, glyph);
        }
        child.type3_rendered_cache.bytes = 0;

        merge_artifact_cache_counts(
            &mut self.path_fill_mask_cache.stats,
            child.path_fill_mask_cache.stats(),
        );
        for (key, mask) in std::mem::take(&mut child.path_fill_mask_cache.entries) {
            self.path_fill_mask_cache.insert(key, mask);
        }
        child.path_fill_mask_cache.bytes = 0;

        merge_artifact_cache_counts(
            &mut self.path_stroke_mask_cache.stats,
            child.path_stroke_mask_cache.stats(),
        );
        for (key, mask) in std::mem::take(&mut child.path_stroke_mask_cache.entries) {
            self.path_stroke_mask_cache.insert(key, mask);
        }
        child.path_stroke_mask_cache.bytes = 0;

        self.path_clip_node_cache
            .absorb_from(std::mem::take(&mut child.path_clip_node_cache));

        for (key, bytes) in child.font_bytes_cache.drain() {
            insert_font_bytes_cache_entry(
                &mut self.font_bytes_cache,
                &mut self.font_bytes_cache_order,
                &mut self.font_bytes_cache_bytes,
                &mut self.font_bytes_cache_stats,
                key,
                bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.font_bytes_cache_stats,
            child.font_bytes_cache_stats,
        );
        child.font_bytes_cache_bytes = 0;
        child.font_bytes_cache_stats = RenderArtifactCacheStats::default();
        for (key, resolver) in child.font_resolver_cache.drain() {
            insert_font_resolver_cache_entry(
                &mut self.font_resolver_cache,
                &mut self.font_resolver_cache_order,
                &mut self.font_resolver_cache_bytes,
                &mut self.font_resolver_cache_stats,
                key,
                resolver,
            );
        }
        merge_artifact_cache_counts(
            &mut self.font_resolver_cache_stats,
            child.font_resolver_cache_stats,
        );
        child.font_resolver_cache_bytes = 0;
        child.font_resolver_cache_stats = RenderArtifactCacheStats::default();
        self.font_resource_key_cache
            .extend(child.font_resource_key_cache.drain());
        self.type3_geometry_cache
            .absorb_from(std::mem::take(&mut child.type3_geometry_cache));
        self.type3_charproc_cache
            .absorb_from(std::mem::take(&mut child.type3_charproc_cache));
        self.type3_retained_charproc_cache
            .absorb_from(std::mem::take(&mut child.type3_retained_charproc_cache));
        let smask_cache_budget = CacheByteBudget {
            max_bytes: self.cache_budget(SMASK_GROUP_CACHE_MAX_BYTES),
            max_entry_bytes: self.cache_entry_budget(SMASK_GROUP_CACHE_MAX_ENTRY_BYTES),
        };
        for (key, mask) in std::mem::take(&mut child.smask_group_cache) {
            insert_smask_group_cache_entry(
                &mut self.smask_group_cache,
                &mut self.smask_group_cache_order,
                &mut self.smask_group_cache_bytes,
                &mut self.smask_group_cache_stats,
                key,
                mask,
                smask_cache_budget,
            );
        }
        merge_artifact_cache_counts(
            &mut self.smask_group_cache_stats,
            child.smask_group_cache_stats,
        );
        child.smask_group_cache_stats = RenderArtifactCacheStats::default();
        child.smask_group_cache_order.clear();
        child.smask_group_cache_bytes = 0;
        let program_cache_budget = CacheByteBudget {
            max_bytes: self.cache_budget(PROGRAM_CACHE_MAX_BYTES),
            max_entry_bytes: self.cache_entry_budget(PROGRAM_CACHE_MAX_ENTRY_BYTES),
        };
        for (key, program) in std::mem::take(&mut child.form_xobject_program_cache) {
            insert_program_cache_entry(
                &mut self.form_xobject_program_cache,
                &mut self.form_xobject_program_cache_order,
                &mut self.form_xobject_program_cache_bytes,
                &mut self.form_xobject_program_cache_stats,
                key,
                program,
                program_cache_budget,
                form_xobject_program_cache_entry_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.form_xobject_program_cache_stats,
            child.form_xobject_program_cache_stats,
        );
        child.form_xobject_program_cache_stats = RenderArtifactCacheStats::default();
        child.form_xobject_program_cache_order.clear();
        child.form_xobject_program_cache_bytes = 0;
        for (key, program) in std::mem::take(&mut child.annotation_appearance_program_cache) {
            insert_program_cache_entry(
                &mut self.annotation_appearance_program_cache,
                &mut self.annotation_appearance_program_cache_order,
                &mut self.annotation_appearance_program_cache_bytes,
                &mut self.annotation_appearance_program_cache_stats,
                key,
                program,
                program_cache_budget,
                form_xobject_program_cache_entry_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.annotation_appearance_program_cache_stats,
            child.annotation_appearance_program_cache_stats,
        );
        child.annotation_appearance_program_cache_stats = RenderArtifactCacheStats::default();
        child.annotation_appearance_program_cache_order.clear();
        child.annotation_appearance_program_cache_bytes = 0;
        for (key, program) in std::mem::take(&mut child.tiling_pattern_program_cache) {
            insert_program_cache_entry(
                &mut self.tiling_pattern_program_cache,
                &mut self.tiling_pattern_program_cache_order,
                &mut self.tiling_pattern_program_cache_bytes,
                &mut self.tiling_pattern_program_cache_stats,
                key,
                program,
                program_cache_budget,
                tiling_pattern_program_cache_entry_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.tiling_pattern_program_cache_stats,
            child.tiling_pattern_program_cache_stats,
        );
        child.tiling_pattern_program_cache_stats = RenderArtifactCacheStats::default();
        child.tiling_pattern_program_cache_order.clear();
        child.tiling_pattern_program_cache_bytes = 0;

        let image_cache_max_bytes = self.cache_budget(RENDER_DOCUMENT_IMAGE_CACHE_MAX_BYTES);
        for (key, raw) in std::mem::take(&mut child.image_xobject_cache) {
            let raw_bytes = raw.byte_count();
            insert_image_xobject_cache_entry(
                &mut self.image_xobject_cache,
                &mut self.image_xobject_cache_order,
                &mut self.image_xobject_cache_bytes,
                key,
                raw,
                raw_bytes,
                image_cache_max_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.image_xobject_cache_stats,
            child.image_xobject_cache_stats,
        );
        child.image_xobject_cache_stats = RenderArtifactCacheStats::default();
        child.image_xobject_cache_order.clear();
        child.image_xobject_cache_bytes = 0;

        let scaled_cache_max_bytes = self.cache_budget(SCALED_IMAGE_CACHE_MAX_BYTES);
        let scaled_cache_max_entry_bytes =
            self.cache_entry_budget(SCALED_IMAGE_CACHE_MAX_ENTRY_BYTES);
        for (key, raw) in std::mem::take(&mut child.scaled_image_cache) {
            insert_scaled_image_cache_entry(
                &mut self.scaled_image_cache,
                &mut self.scaled_image_cache_order,
                &mut self.scaled_image_cache_bytes,
                key,
                raw,
                scaled_cache_max_bytes,
                scaled_cache_max_entry_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.scaled_image_cache_stats,
            child.scaled_image_cache_stats,
        );
        child.scaled_image_cache_stats = RenderArtifactCacheStats::default();
        child.scaled_image_cache_order.clear();
        child.scaled_image_cache_bytes = 0;

        let shading_cache_max_bytes = self.cache_budget(SHADING_MESH_CACHE_MAX_BYTES);
        let shading_cache_max_entry_bytes =
            self.cache_entry_budget(SHADING_MESH_CACHE_MAX_ENTRY_BYTES);
        for (key, bytes) in std::mem::take(&mut child.shading_mesh_cache) {
            insert_shading_mesh_cache_entry(
                &mut self.shading_mesh_cache,
                &mut self.shading_mesh_cache_order,
                &mut self.shading_mesh_cache_bytes,
                key,
                bytes,
                shading_cache_max_bytes,
                shading_cache_max_entry_bytes,
            );
        }
        merge_artifact_cache_counts(
            &mut self.shading_mesh_cache_stats,
            child.shading_mesh_cache_stats,
        );
        child.shading_mesh_cache_stats = RenderArtifactCacheStats::default();
        child.shading_mesh_cache_order.clear();
        child.shading_mesh_cache_bytes = 0;

        for pooled in child.offscreen_buffer_pool.drain(..) {
            self.recycle_offscreen_buffer(pooled);
        }

        // Merge font substitution events from child state.
        self.font_substitution_log
            .absorb(std::mem::take(&mut child.font_substitution_log));
    }

    fn shading_mesh_data(
        &mut self,
        shading_obj: &PdfObject,
        shading_dict: &PdfDictionary,
        reader: &crate::reader::PdfReader,
    ) -> Option<Arc<Vec<u8>>> {
        let st = shading_dict.get_integer("ShadingType")?;
        if !(4..=7).contains(&st) {
            return None;
        }
        let cache_key = shading_mesh_cache_key(
            shading_obj,
            st,
            self.page_number,
            &self.render_contract_fingerprint,
        );
        if let Some(key) = cache_key.as_deref() {
            if let Some(cached) = self.shading_mesh_cache.get(key) {
                touch_shading_mesh_cache_key(&mut self.shading_mesh_cache_order, key);
                self.shading_mesh_cache_stats.hits =
                    self.shading_mesh_cache_stats.hits.saturating_add(1);
                return Some(Arc::clone(cached));
            }
            self.shading_mesh_cache_stats.misses =
                self.shading_mesh_cache_stats.misses.saturating_add(1);
        }
        let (dict, raw) = resolve_to_stream(shading_obj, reader)?;
        let stream_obj = PdfObject::Stream { dict, raw };
        let bytes = self
            .scheduled_decode_stream(&stream_obj, reader, "renderer mesh shading stream decode")
            .ok()?;
        let bytes = Arc::new(bytes);
        if let Some(key) = cache_key {
            let cache_max_bytes = self.cache_budget(SHADING_MESH_CACHE_MAX_BYTES);
            let cache_max_entry_bytes = self.cache_entry_budget(SHADING_MESH_CACHE_MAX_ENTRY_BYTES);
            insert_shading_mesh_cache_entry(
                &mut self.shading_mesh_cache,
                &mut self.shading_mesh_cache_order,
                &mut self.shading_mesh_cache_bytes,
                key,
                Arc::clone(&bytes),
                cache_max_bytes,
                cache_max_entry_bytes,
            );
        }
        Some(bytes)
    }

    fn cached_form_xobject_program(
        &mut self,
        name: &str,
        obj_num: u32,
        gen_num: u16,
        resolved_bbox: Option<[f64; 4]>,
        resolved_matrix: Option<[f64; 6]>,
    ) -> Option<Arc<FormXObjectProgram>> {
        let parent_resource_fingerprint = page_resources_fingerprint(&self.resources);
        let cache_key = form_xobject_program_cache_key(
            obj_num,
            gen_num,
            self.page_number,
            &self.render_contract_fingerprint,
            parent_resource_fingerprint,
        );
        if let Some(cached) = self.form_xobject_program_cache.get(&cache_key) {
            touch_program_cache_key(&mut self.form_xobject_program_cache_order, &cache_key);
            self.form_xobject_program_cache_stats.hits =
                self.form_xobject_program_cache_stats.hits.saturating_add(1);
            return cached.as_ref().map(Arc::clone);
        }
        self.form_xobject_program_cache_stats.misses = self
            .form_xobject_program_cache_stats
            .misses
            .saturating_add(1);

        let reader = self.engine.document().reader();
        let (form_dict, raw_bytes) = match reader.get_object(obj_num, gen_num) {
            Ok(PdfObject::Stream { dict, raw }) => (dict, raw),
            Ok(_) => {
                self.record_fatal_render_error(format!(
                    "Form XObject resource /{name} did not resolve to a stream"
                ));
                self.insert_form_xobject_program_cache_entry(cache_key, None);
                return None;
            }
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "Form XObject resource /{name} failed to resolve: {err}"
                ));
                self.insert_form_xobject_program_cache_entry(cache_key, None);
                return None;
            }
        };

        if form_dict.get_name("Subtype") != Some("Form") {
            self.record_fatal_render_error(format!(
                "Form XObject resource /{name} is not /Subtype /Form"
            ));
            self.insert_form_xobject_program_cache_entry(cache_key, None);
            return None;
        }
        let bbox_label = format!("Form XObject resource /{name}");
        let form_bbox = if let Some(bbox) = resolved_bbox {
            bbox
        } else {
            match required_bbox(&form_dict, &bbox_label) {
                Ok(bbox) => bbox,
                Err(err) => {
                    self.record_fatal_render_error(err);
                    self.insert_form_xobject_program_cache_entry(cache_key, None);
                    return None;
                }
            }
        };

        let stream_obj = PdfObject::Stream {
            dict: form_dict.clone(),
            raw: raw_bytes,
        };
        let content_bytes = match self.scheduled_decode_stream(
            &stream_obj,
            reader,
            "renderer Form XObject program stream decode",
        ) {
            Ok(bytes) => bytes,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "Form XObject resource /{name} stream decode failed: {err}"
                ));
                self.insert_form_xobject_program_cache_entry(cache_key, None);
                return None;
            }
        };
        let ops = match crate::content::ContentParser::parse(&content_bytes) {
            Ok(ops) => ops,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "Form XObject resource /{name} content parse failed: {err}"
                ));
                self.insert_form_xobject_program_cache_entry(cache_key, None);
                return None;
            }
        };
        let resources = form_dict
            .get("Resources")
            .map(|res_obj| crate::engine::parse_resources_from_obj(res_obj, reader));
        let mut retained_resources = self.resources.clone();
        if let Some(form_res) = resources.as_ref() {
            overlay_page_resources(&mut retained_resources, form_res);
        }
        let is_transparency_group = is_transparency_group(&form_dict);
        let (retained_plan, retained_plan_refusal) = retained_plan_cache_fields(
            self.compile_form_xobject_retained_plan(name, &ops, &retained_resources),
        );
        let form_matrix = if let Some(matrix) = resolved_matrix {
            matrix
        } else {
            match extract_form_matrix(&form_dict) {
                Ok(matrix) => matrix,
                Err(err) => {
                    self.record_fatal_render_error(format!(
                        "Form XObject resource /{name} malformed /Matrix: {err}"
                    ));
                    self.insert_form_xobject_program_cache_entry(cache_key, None);
                    return None;
                }
            }
        };
        let program = Arc::new(FormXObjectProgram {
            form_matrix,
            bbox: Some(form_bbox),
            is_transparency_group,
            dict: form_dict,
            ops: Arc::new(ops),
            resources,
            retained_plan,
            retained_plan_refusal,
        });
        self.insert_form_xobject_program_cache_entry(cache_key, Some(Arc::clone(&program)));
        Some(program)
    }

    fn cached_tiling_pattern_program(
        &mut self,
        cache_key: &str,
        pat_dict: &PdfDictionary,
        raw_bytes: Vec<u8>,
        resources: &PageResources,
    ) -> Option<Arc<TilingPatternProgram>> {
        if let Some(cached) = self.tiling_pattern_program_cache.get(cache_key) {
            touch_program_cache_key(&mut self.tiling_pattern_program_cache_order, cache_key);
            self.tiling_pattern_program_cache_stats.hits = self
                .tiling_pattern_program_cache_stats
                .hits
                .saturating_add(1);
            return cached.as_ref().map(Arc::clone);
        }
        self.tiling_pattern_program_cache_stats.misses = self
            .tiling_pattern_program_cache_stats
            .misses
            .saturating_add(1);

        let reader = self.engine.document().reader();
        let stream_obj = PdfObject::Stream {
            dict: pat_dict.clone(),
            raw: raw_bytes,
        };
        let content_bytes = match self.scheduled_decode_stream(
            &stream_obj,
            reader,
            "renderer tiling pattern program stream decode",
        ) {
            Ok(bytes) => bytes,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "tiling pattern content decode failed: {err}"
                ));
                self.insert_tiling_pattern_program_cache_entry(cache_key.to_string(), None);
                return None;
            }
        };
        let ops = match crate::content::ContentParser::parse(&content_bytes) {
            Ok(ops) => ops,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "tiling pattern content parse failed: {err}"
                ));
                self.insert_tiling_pattern_program_cache_entry(cache_key.to_string(), None);
                return None;
            }
        };
        let (retained_plan, retained_plan_refusal) =
            retained_plan_cache_fields(self.compile_tiling_pattern_retained_plan(&ops, resources));
        let program = Arc::new(TilingPatternProgram {
            ops: Arc::new(ops),
            resources: resources.clone(),
            retained_plan,
            retained_plan_refusal,
        });
        self.insert_tiling_pattern_program_cache_entry(
            cache_key.to_string(),
            Some(Arc::clone(&program)),
        );
        Some(program)
    }

    fn compile_tiling_pattern_retained_plan(
        &self,
        ops: &[ContentOperation],
        resources: &PageResources,
    ) -> std::result::Result<Arc<RenderPlan>, String> {
        let result = self.compile_supported_retained_replay_plan(ops, resources);
        if let Err(err) = &result {
            log::debug!("tiling pattern: retained plan unavailable: {err}");
        }
        result
    }

