    fn compile_supported_retained_replay_plan(
        &self,
        ops: &[ContentOperation],
        resources: &PageResources,
    ) -> std::result::Result<Arc<RenderPlan>, String> {
        let list = build_display_list(ops, self.viewport.clone(), resources);
        if !list.is_fully_supported() {
            return Err(unsupported_display_list_reasons(&list));
        }
        let contract = self
            .current_retained_plan_contract()
            .ok_or_else(|| "retained plan contract is unavailable".to_string())?;
        match RenderPlan::compile_with_resources(list, contract, resources) {
            Ok(plan) => {
                if let Some(refusal) =
                    plan.packed
                        .descriptors
                        .iter()
                        .find_map(|descriptor| match descriptor {
                            NativeDescriptor::CompileRefusal(refusal) => Some(refusal),
                            _ => None,
                        })
                {
                    return Err(refusal.to_string());
                }
                if !plan.packed.has_only_supported_descriptors() {
                    return Err(
                        "compiled retained subprogram contains unsupported native descriptors"
                            .to_string(),
                    );
                }
                Ok(Arc::new(plan))
            }
            Err(err) => Err(format!("retained plan compile failed: {err}")),
        }
    }

    fn current_retained_plan_contract(&self) -> Option<RenderContract> {
        let page = self.engine.get_page(self.page_number).ok()?;
        let page_identity = self.engine.canonical_document().page_identity_for(&page);
        let mut contract = RenderContract::for_viewport(
            self.engine.canonical_document().revision(),
            page_identity.object.id,
            self.page_number,
            &self.viewport,
            RenderTile::full(self.viewport.width_px, self.viewport.height_px),
            self.buf.render_mode(),
        );
        contract.optional_content = self
            .optional_content
            .visibility_fingerprint()
            .to_string()
            .into();
        contract.resource_budget = self.resource_budget;
        contract.exactness = self.exactness_policy;
        contract.print_profile = self.print_profile;
        contract.annotations = self.annotation_policy;
        contract.forms = self.form_policy;
        Some(contract)
    }

    fn cached_annotation_appearance_program(
        &mut self,
        name: &str,
        annot_obj: &PdfObject,
        annot_index: usize,
        form_dict: &PdfDictionary,
        raw_bytes: Vec<u8>,
        rect: [f64; 4],
    ) -> Option<Arc<FormXObjectProgram>> {
        let cache_key = annotation_appearance_program_cache_key(
            annot_obj,
            annot_index,
            form_dict,
            &raw_bytes,
            rect,
            self.page_number,
            &self.render_contract_fingerprint,
        );
        if let Some(cached) = self.annotation_appearance_program_cache.get(&cache_key) {
            touch_program_cache_key(
                &mut self.annotation_appearance_program_cache_order,
                &cache_key,
            );
            self.annotation_appearance_program_cache_stats.hits = self
                .annotation_appearance_program_cache_stats
                .hits
                .saturating_add(1);
            return cached.as_ref().map(Arc::clone);
        }
        self.annotation_appearance_program_cache_stats.misses = self
            .annotation_appearance_program_cache_stats
            .misses
            .saturating_add(1);

        if form_dict.get_name("Subtype") != Some("Form") {
            self.insert_annotation_appearance_program_cache_entry(cache_key, None);
            return None;
        }
        let appearance_label = format!("annotation appearance '{name}'");
        let bbox = match required_bbox(form_dict, &appearance_label) {
            Ok(bbox) => bbox,
            Err(err) => {
                self.record_fatal_render_error(err);
                self.insert_annotation_appearance_program_cache_entry(cache_key, None);
                return None;
            }
        };

        let stream_obj = PdfObject::Stream {
            dict: form_dict.clone(),
            raw: raw_bytes,
        };
        let reader = self.engine.document().reader();
        let content_bytes = match self.scheduled_decode_stream(
            &stream_obj,
            reader,
            "renderer annotation appearance program stream decode",
        ) {
            Ok(bytes) => bytes,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "annotation appearance '{name}' stream decode failed: {err}"
                ));
                self.insert_annotation_appearance_program_cache_entry(cache_key, None);
                return None;
            }
        };
        let ops = match crate::content::ContentParser::parse(&content_bytes) {
            Ok(ops) => ops,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "annotation appearance '{name}' content parse failed: {err}"
                ));
                self.insert_annotation_appearance_program_cache_entry(cache_key, None);
                return None;
            }
        };
        let resources = form_dict
            .get("Resources")
            .map(|res_obj| crate::engine::parse_resources_from_obj(res_obj, reader));
        let mut retained_resources = self.resources.clone();
        if let Some(form_res) = resources.as_ref() {
            overlay_page_resources(&mut retained_resources, form_res);
        }
        let (retained_plan, retained_plan_refusal) = retained_plan_cache_fields(
            self.compile_annotation_appearance_retained_plan(&ops, &retained_resources),
        );
        let form_matrix = match extract_form_matrix(form_dict) {
            Ok(matrix) => matrix,
            Err(err) => {
                self.record_fatal_render_error(format!(
                    "annotation appearance '{name}' malformed /Matrix: {err}"
                ));
                self.insert_annotation_appearance_program_cache_entry(cache_key, None);
                return None;
            }
        };
        let program = Arc::new(FormXObjectProgram {
            form_matrix,
            bbox: Some(bbox),
            is_transparency_group: is_transparency_group(form_dict),
            dict: form_dict.clone(),
            ops: Arc::new(ops),
            resources,
            retained_plan,
            retained_plan_refusal,
        });
        self.insert_annotation_appearance_program_cache_entry(
            cache_key,
            Some(Arc::clone(&program)),
        );
        Some(program)
    }

    fn insert_form_xobject_program_cache_entry(
        &mut self,
        key: String,
        program: Option<Arc<FormXObjectProgram>>,
    ) {
        let budget = CacheByteBudget {
            max_bytes: self.cache_budget(PROGRAM_CACHE_MAX_BYTES),
            max_entry_bytes: self.cache_entry_budget(PROGRAM_CACHE_MAX_ENTRY_BYTES),
        };
        insert_program_cache_entry(
            &mut self.form_xobject_program_cache,
            &mut self.form_xobject_program_cache_order,
            &mut self.form_xobject_program_cache_bytes,
            &mut self.form_xobject_program_cache_stats,
            key,
            program,
            budget,
            form_xobject_program_cache_entry_bytes,
        );
    }

