    #[test]
    fn clip_identity_scope_tracks_contract_and_tile_identity() {
        let viewport = Viewport::new([0.0, 0.0, 10.0, 12.0], 72)
            .with_device_transform(Transform2D::translation(3.0, 5.0));
        let tile_viewport = viewport.pixel_window(1, 2, 8, 9);
        let base = clip_identity_scope_for_render_state(11, "contract:a", 1, &viewport);
        let other_revision = clip_identity_scope_for_render_state(12, "contract:a", 1, &viewport);
        let other_contract = clip_identity_scope_for_render_state(11, "contract:b", 1, &viewport);
        let other_tile = clip_identity_scope_for_render_state(11, "contract:a", 1, &tile_viewport);

        assert_eq!(base.revision_identity, 11);
        assert_ne!(base.revision_identity, other_revision.revision_identity);
        assert_ne!(base.render_contract_identity, 0);
        assert_ne!(
            base.render_contract_identity,
            other_contract.render_contract_identity
        );
        assert_eq!(base.tile_identity, other_contract.tile_identity);
        assert_ne!(base.tile_identity, other_tile.tile_identity);
    }

    #[test]
    fn render_state_clip_dag_uses_active_contract_scope() {
        let engine = ContentEngine::open_path(fixture("image_only.pdf")).expect("open fixture");
        let mut state = blank_render_state(&engine);

        let legacy_scope = state.clip_identity_scope();
        let legacy_full = state.clip_dag.full();
        assert_eq!(
            legacy_full.revision_identity,
            legacy_scope.revision_identity
        );
        assert_eq!(
            legacy_full.render_contract_identity,
            legacy_scope.render_contract_identity
        );
        assert_eq!(legacy_full.tile_identity, legacy_scope.tile_identity);

        state.apply_render_contract_identity("contract:a", RenderResourceBudget::default());

        let active_scope = state.clip_identity_scope();
        let active_full = state.clip_dag.full();
        assert_eq!(
            active_full.revision_identity,
            active_scope.revision_identity
        );
        assert_eq!(
            active_full.render_contract_identity,
            active_scope.render_contract_identity
        );
        assert_eq!(active_full.tile_identity, active_scope.tile_identity);
        assert_ne!(
            legacy_full.render_contract_identity,
            active_full.render_contract_identity
        );

        let buf_w = state.buf.width;
        let buf_h = state.buf.height;
        let rect = state.clip_dag.rectangle(1, 1, 4, 4, buf_w, buf_h);
        assert_eq!(rect.revision_identity, active_scope.revision_identity);
        assert_eq!(
            rect.render_contract_identity,
            active_scope.render_contract_identity
        );
        assert_eq!(rect.tile_identity, active_scope.tile_identity);
        assert_eq!(rect.stable_id, active_scope.stable_id_for(&rect.state));
    }

