    #[test]
    fn color_glyph_surface_denial_declines_color_fill_for_outline_fallback() {
        let engine = ContentEngine::open_path(fixture("image_only.pdf")).expect("open fixture");
        let mut state = blank_render_state(&engine);
        state.temporary_scheduler = RenderDecodeScheduler::new(&DecodeLimits {
            scheduler_memory_budget_bytes: 1,
            ..DecodeLimits::default()
        });
        let font_bytes = include_bytes!("../../fonts/LiberationSans-Regular.ttf").as_slice();
        let variation = VariationRequest::none();
        let glyph_id = crate::render::color_glyph::resolve_request_glyph_id(
            font_bytes,
            false,
            b'A' as u16,
            'A',
            Some("A"),
            &variation,
        )
        .expect("bundled LiberationSans should resolve A");
        let request = GlyphRenderRequest {
            font_name: "LiberationSans-Regular",
            font_subtype: FontSubtype::TrueType,
            code: b'A' as u16,
            ch: 'A',
            glyph_name: Some("A"),
            is_gid: false,
            font_bytes,
            font_hash: 0xA11CE,
            variation: &variation,
            upem: 1000.0,
            light_hinting_supported: true,
            offset_x: 0.0,
            offset_y: 0.0,
        };
        let op = crate::render::color_glyph::ColrPaintOp {
            glyph_id: glyph_id.0,
            transform: Transform2D::identity(),
            paint: crate::render::color_glyph::ColrPaint::Solid(RED),
            clips: Vec::new(),
            blend_mode: crate::render::color_glyph::ColrBlendMode::Normal,
        };

        assert!(
            !state.paint_colr_paint_ops(
                &request,
                &[op],
                &Transform2D::identity(),
                GlyphHinting::disabled(),
            ),
            "over-budget color glyph paint must decline so normal outline fallback can paint"
        );
        let metrics = state.temporary_scheduler.metrics();
        assert_eq!(metrics.jobs, 1);
        assert_eq!(metrics.rejected_jobs, 1);
        assert_eq!(metrics.failed_jobs, 1);
    }

