    #[test]
    fn scheduled_raw_window_decode_uses_planned_source_region_cache_key() {
        let pixels = [
            0u8, 1, 2, 10, 11, 12, 20, 21, 22, 30, 31, 32, 40, 41, 42, 50, 51, 52, 60, 61, 62, 70,
            71, 72, 80, 81, 82, 90, 91, 92, 100, 101, 102, 110, 111, 112,
        ];
        let mut pdf = b"%PDF-1.4\n".to_vec();
        let mut off = [0usize; 5];
        off[1] = pdf.len();
        pdf.extend_from_slice(b"1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
        off[2] = pdf.len();
        pdf.extend_from_slice(b"2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
        off[3] = pdf.len();
        pdf.extend_from_slice(
            b"3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 10 10] >>\nendobj\n",
        );
        off[4] = pdf.len();
        pdf.extend_from_slice(
            format!(
                "4 0 obj\n<< /Type /XObject /Subtype /Image /Width 4 /Height 3 /BitsPerComponent 8 /ColorSpace /DeviceRGB /Length {} >>\nstream\n",
                pixels.len()
            )
            .as_bytes(),
        );
        pdf.extend_from_slice(&pixels);
        pdf.extend_from_slice(b"\nendstream\nendobj\n");
        let xref = pdf.len();
        pdf.extend_from_slice(b"xref\n0 5\n0000000000 65535 f \n");
        for offset in off.iter().take(5).skip(1) {
            pdf.extend_from_slice(format!("{offset:010} 00000 n \n").as_bytes());
        }
        pdf.extend_from_slice(
            format!("trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n").as_bytes(),
        );

        let engine = ContentEngine::open_bytes(pdf).expect("open raw image fixture");
        let mut state = blank_render_state(&engine);
        let image_ref = ImageReference {
            page_number: 1,
            xobject_name: "ImRaw".to_string(),
            object_number: 4,
            generation_number: 0,
            width: 4,
            height: 3,
            bits_per_component: 8,
            color_space: "DeviceRGB".to_string(),
            filter: vec![],
            is_inline: false,
            is_mask: false,
            is_smask: false,
            inline_data: None,
        };

        let raw = state
            .scheduled_decode_raw_window_with_cache_key(
                &image_ref,
                None,
                RawImageDecodeWindow {
                    x: 1,
                    y: 1,
                    width: 2,
                    height: 2,
                },
                RawImageComponentSelection::All,
                "planned:raw-window",
                "test raw window",
            )
            .expect("raw window decode");

        assert_eq!(raw.width, 2);
        assert_eq!(raw.height, 2);
        assert_eq!(
            raw.pixels,
            vec![50, 51, 52, 60, 61, 62, 90, 91, 92, 100, 101, 102]
        );
        assert!(state.image_xobject_cache.contains_key("planned:raw-window"));
        assert_eq!(state.image_xobject_cache_stats.misses, 1);
    }

