    #[test]
    fn high_quality_render_refuses_generic_bundled_font_substitution() {
        let pdf = simple_nonembedded_font_pdf("SomeCorporateSans");
        let engine = ContentEngine::open_bytes(pdf).expect("open non-embedded font PDF");

        engine
            .render_page_with_mode(1, 72, RenderMode::Compat)
            .expect("compat render may use deterministic bundled font substitution");

        let error = engine
            .render_page_with_mode(1, 72, RenderMode::HighQuality)
            .expect_err("high-quality render must refuse generic bundled font substitution");
        assert!(matches!(
            error,
            WellfriendError::UnsupportedFeature(message)
                if message.contains("font /F1 (SomeCorporateSans)")
                    && message.contains("no valid embedded or document-provided program")
                    && message.contains("no configured deterministic replacement")
        ));
    }

    #[test]
    fn high_quality_render_accepts_deterministic_system_font_mapping() {
        let pdf = simple_nonembedded_font_pdf("ArialMT");
        let engine = ContentEngine::open_bytes(pdf).expect("open non-embedded Arial alias PDF");

        let (_buffer, log) = engine
            .render_page_with_font_substitution_report(1, 72, RenderMode::Compat)
            .expect("compat render should report deterministic system mapping");
        let event = log
            .events()
            .iter()
            .find(|event| event.requested_pdf_font == "ArialMT")
            .expect("deterministic system mapping event");
        assert_eq!(
            event.reason,
            crate::render::font_substitution_report::FontSubstitutionReason::DeterministicSystemMapping
        );
        assert_eq!(event.resolution_source, "deterministic_system_mapping");
        assert_eq!(event.selection_reason, "deterministic_system_mapping");
        assert_eq!(event.selected_fallback, "LiberationSans-Regular");
        assert_eq!(
            event.metric_posture,
            crate::render::font_substitution_report::FontSubstitutionMetricPosture::MetricCompatible
        );
        assert!(
            event
                .risk_flags
                .contains(&"source_deterministic_system_mapping".to_string()),
            "{:?}",
            event.risk_flags
        );

        engine
            .render_page_with_mode(1, 72, RenderMode::HighQuality)
            .expect("high-quality render should allow deterministic system mapping");
    }

    #[test]
    fn high_quality_render_accepts_caller_registered_font_mapping() {
        let pdf = simple_nonembedded_font_pdf("SomeCorporateSans");
        let mut engine =
            ContentEngine::open_bytes(pdf).expect("open non-embedded registered font PDF");
        let registered_bytes = get_fallback_font("Helvetica")
            .expect("test fixture font bytes")
            .to_vec();
        engine
            .register_font_bytes("SomeCorporateSans", registered_bytes)
            .expect("register caller-owned font bytes");

        let (_buffer, log) = engine
            .render_page_with_font_substitution_report(1, 72, RenderMode::Compat)
            .expect("compat render should report caller-registered mapping");
        let event = log
            .events()
            .iter()
            .find(|event| event.requested_pdf_font == "SomeCorporateSans")
            .expect("caller-registered mapping event");
        assert_eq!(
            event.reason,
            crate::render::font_substitution_report::FontSubstitutionReason::DocumentProvided
        );
        assert_eq!(event.resolution_source, "user_registered");
        assert_eq!(event.selection_reason, "user_registered_direct_match");
        assert_eq!(event.selected_fallback, "LiberationSans-Regular");
        assert!(
            event
                .font_policy_identity
                .contains("font_provider:registered-fonts:1:"),
            "{}",
            event.font_policy_identity
        );
        assert!(
            event
                .risk_flags
                .contains(&"source_document_provided_font".to_string()),
            "{:?}",
            event.risk_flags
        );

        engine
            .render_page_with_mode(1, 72, RenderMode::HighQuality)
            .expect("high-quality render should allow caller-registered font bytes");
    }

    #[test]
    fn symbolic_descriptor_routes_generic_compat_fallback_to_coverage_face() {
        let pdf = simple_nonembedded_font_pdf_with_descriptor_flags("CorporatePi", 1 << 2);
        let engine = ContentEngine::open_bytes(pdf).expect("open symbolic fallback PDF");

        let (_buffer, log) = engine
            .render_page_with_font_substitution_report(1, 72, RenderMode::Compat)
            .expect("compat render may use deterministic symbolic fallback");
        let event = log
            .events()
            .iter()
            .find(|event| event.requested_pdf_font == "CorporatePi")
            .expect("symbolic fallback event");
        assert_eq!(event.resolution_source, "bundled_fallback");
        assert_eq!(event.selection_reason, "symbolic_flag");
        assert_eq!(event.selected_fallback, "DejaVuSans");
        assert_eq!(
            event.metric_posture,
            crate::render::font_substitution_report::FontSubstitutionMetricPosture::CoverageOnly
        );

        let error = engine
            .render_page_with_mode(1, 72, RenderMode::HighQuality)
            .expect_err("high-quality render must still refuse generic symbolic fallback");
        assert!(matches!(
            error,
            WellfriendError::UnsupportedFeature(message)
                if message.contains("font /F1 (CorporatePi)")
                    && message.contains("no configured deterministic replacement")
        ));
    }

    #[test]
    fn renderer_type0_odd_text_code_returns_typed_refusal() {
        let engine = ContentEngine::open_path(fixture("image_only.pdf")).expect("open fixture");
        let mut state = blank_render_state(&engine);
        let mut font = PdfDictionary::empty();
        font.insert("Type", PdfObject::Name("Font".to_string()));
        font.insert("Subtype", PdfObject::Name("Type0".to_string()));
        font.insert("BaseFont", PdfObject::Name("TestCID".to_string()));
        font.insert("Encoding", PdfObject::Name("Identity-H".to_string()));
        state.resources.fonts.insert("F1".to_string(), font);
        state.gs.text.font_name = "F1".to_string();
        state.gs.text.font_size = 12.0;

        state.render_text_string(&[0x00, 0x48, 0x56]);
        let error = state
            .check_fatal_render_error()
            .expect_err("odd Type0 text bytes must fail closed instead of padding a CID");
        assert!(
            format!("{error}").contains("incomplete 2-byte character code"),
            "got {error}"
        );
    }

    #[test]
    fn skips_non_cid_replacement_and_control_glyph_painting() {
        assert!(!should_paint_decoded_glyph(&decoded_glyph(
            '\u{FFFD}', false, None
        )));
        assert!(!should_paint_decoded_glyph(&decoded_glyph(
            '\u{FFFD}',
            false,
            Some(".notdef")
        )));
        assert!(!should_paint_decoded_glyph(&decoded_glyph(
            '\0', false, None
        )));
        assert!(should_paint_decoded_glyph(&decoded_glyph(
            '\u{FFFD}',
            false,
            Some("G1")
        )));
        assert!(should_paint_decoded_glyph(&decoded_glyph('A', false, None)));
        assert!(should_paint_decoded_glyph(&decoded_glyph(
            '\u{FFFD}', true, None
        )));
    }

    #[test]
    fn exact_text_advance_requires_real_metric_source() {
        let glyph = decoded_glyph('A', false, None);
        let font_bytes = get_fallback_font("Helvetica").expect("standard fallback font");
        let advance = decoded_text_horizontal_advance(
            ExactnessPolicy::HighQualityExact,
            "Helvetica",
            &glyph,
            None,
            Some(font_bytes),
            &VariationRequest::none(),
            false,
        )
        .expect("standard fallback font has real metrics");
        assert!(advance > 0.0);

        let error = decoded_text_horizontal_advance(
            ExactnessPolicy::HighQualityExact,
            "BrokenFont",
            &glyph,
            Some(500.0),
            Some(b"not a font program"),
            &VariationRequest::none(),
            false,
        )
        .expect_err("exact mode must reject synthetic fallback advances");
        assert!(
            error.contains("no real font advance metric"),
            "unexpected error: {error}"
        );
    }

    #[test]
    fn compat_text_advance_keeps_legacy_default_without_metrics() {
        let glyph = decoded_glyph('A', false, None);
        let advance = decoded_text_horizontal_advance(
            ExactnessPolicy::Compatibility,
            "BrokenFont",
            &glyph,
            None,
            Some(b"not a font program"),
            &VariationRequest::none(),
            false,
        )
        .expect("compat mode keeps best-effort text positioning");
        assert_eq!(advance, 500.0);
    }

    #[test]
    fn vertical_text_advance_requires_vertical_metric() {
        let mut glyph = decoded_glyph('A', true, None);
        glyph.is_vertical = true;

        let error = decoded_text_vertical_advance(&glyph)
            .expect_err("vertical writing must not synthesize -1000 advance");
        assert!(
            error.contains("no vertical advance metric"),
            "unexpected error: {error}"
        );

        glyph.vertical_advance = Some(-880.0);
        assert_eq!(decoded_text_vertical_advance(&glyph), Ok(-880.0));
    }

    fn simple_pdf_with_extgstate(
        content: &str,
        extgstates: &[&str],
        extgstate_resources: &str,
    ) -> Vec<u8> {
        fn add_obj(objects: &mut Vec<Vec<u8>>, body: impl AsRef<[u8]>) -> usize {
            objects.push(body.as_ref().to_vec());
            objects.len()
        }

        let mut objects = Vec::new();
        let font = add_obj(
            &mut objects,
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        );
        let ext_ids: Vec<usize> = extgstates
            .iter()
            .map(|body| add_obj(&mut objects, body.as_bytes()))
            .collect();
        let stream = format!(
            "<< /Length {} >>\nstream\n{}\nendstream",
            content.len(),
            content
        );
        let contents = add_obj(&mut objects, stream.as_bytes());
        let page = objects.len() + 1;
        let pages = objects.len() + 2;
        let root = objects.len() + 3;
        let resources = extgstate_resources
            .replace("{font}", &font.to_string())
            .replace("{gs1}", &ext_ids[0].to_string())
            .replace("{gs2}", &ext_ids[1].to_string());
        add_obj(
            &mut objects,
            format!(
                "<< /Type /Page /Parent {} 0 R /MediaBox [0 0 100 100] \
                 /Resources {} /Contents {} 0 R >>",
                pages, resources, contents
            )
            .as_bytes(),
        );
        add_obj(
            &mut objects,
            format!("<< /Type /Pages /Kids [{} 0 R] /Count 1 >>", page).as_bytes(),
        );
        add_obj(
            &mut objects,
            format!("<< /Type /Catalog /Pages {} 0 R >>", pages).as_bytes(),
        );

        let mut out = bytearray_pdf_header();
        let mut offsets = vec![0usize];
        for (idx, obj) in objects.iter().enumerate() {
            offsets.push(out.len());
            out.extend_from_slice(format!("{} 0 obj\n", idx + 1).as_bytes());
            out.extend_from_slice(obj);
            out.extend_from_slice(b"\nendobj\n");
        }
        let startxref = out.len();
        out.extend_from_slice(format!("xref\n0 {}\n", objects.len() + 1).as_bytes());
        out.extend_from_slice(b"0000000000 65535 f \n");
        for offset in offsets.iter().skip(1) {
            out.extend_from_slice(format!("{:010} 00000 n \n", offset).as_bytes());
        }
        out.extend_from_slice(
            format!(
                "trailer\n<< /Size {} /Root {} 0 R >>\nstartxref\n{}\n%%EOF\n",
                objects.len() + 1,
                root,
                startxref
            )
            .as_bytes(),
        );
        out
    }

    fn bytearray_pdf_header() -> Vec<u8> {
        b"%PDF-1.7\n%\xE2\xE3\xCF\xD3\n".to_vec()
    }

