    #[test]
    fn transparent_page_group_cache_evicts_lru_and_prunes_order_on_invalidation() {
        let mut cache = RenderDocumentCache::new();
        let hot_key = RenderDocumentCache::transparent_page_group_key_with_revision(
            99_999,
            "revision:hot",
            "contract:hot",
        );
        cache.insert_transparent_page_group(hot_key.clone(), true);
        for page in 0..(TRANSPARENT_PAGE_GROUP_CACHE_ENTRIES - 1) {
            cache.insert_transparent_page_group(
                RenderDocumentCache::transparent_page_group_key_with_revision(
                    page,
                    "revision:cold",
                    "contract:cold",
                ),
                false,
            );
        }
        assert_eq!(
            cache.transparent_page_group_entries(),
            TRANSPARENT_PAGE_GROUP_CACHE_ENTRIES
        );

        assert_eq!(cache.cached_transparent_page_group(&hot_key), Some(true));
        cache.insert_transparent_page_group(
            RenderDocumentCache::transparent_page_group_key_with_revision(
                100_000,
                "revision:new",
                "contract:new",
            ),
            false,
        );

        assert_eq!(
            cache.transparent_page_group_entries(),
            TRANSPARENT_PAGE_GROUP_CACHE_ENTRIES
        );
        assert_eq!(
            cache.cached_transparent_page_group(&hot_key),
            Some(true),
            "hot transparent-page-group decision must survive LRU pressure"
        );
        assert_eq!(
            cache.cached_transparent_page_group(
                &RenderDocumentCache::transparent_page_group_key_with_revision(
                    0,
                    "revision:cold",
                    "contract:cold"
                )
            ),
            None,
            "oldest cold transparent-page-group decision should be evicted first"
        );

        let stale_key = RenderDocumentCache::transparent_page_group_key_with_revision(
            42,
            "revision:stale",
            "contract:stale",
        );
        cache.insert_transparent_page_group(stale_key.clone(), true);
        assert!(cache
            .transparent_page_group_cache_order
            .iter()
            .any(|key| key == &stale_key));

        cache.invalidate_page_artifacts(&[42]);

        assert_eq!(cache.cached_transparent_page_group(&stale_key), None);
        assert!(!cache
            .transparent_page_group_cache_order
            .iter()
            .any(|key| key == &stale_key));
    }

    #[test]
    fn transparent_page_group_key_includes_render_contract_identity() {
        let base = RenderDocumentCache::transparent_page_group_key_with_revision(
            1,
            "revision:a",
            "contract:a",
        );
        let other_contract = RenderDocumentCache::transparent_page_group_key_with_revision(
            1,
            "revision:a",
            "contract:b",
        );
        let other_revision = RenderDocumentCache::transparent_page_group_key_with_revision(
            1,
            "revision:b",
            "contract:a",
        );

        assert_ne!(
            base, other_contract,
            "transparent-page-group decisions must not cross render contracts"
        );
        assert_ne!(
            base, other_revision,
            "transparent-page-group decisions must remain revision-scoped"
        );
        assert!(
            base.starts_with("page:1:"),
            "page artifact invalidation relies on the page-prefixed key"
        );
    }

    #[test]
    fn transparent_page_group_ignores_complete_no_paint_blend_state() {
        let mut dict = PdfDictionary::empty();
        dict.insert("Type", PdfObject::Name("ExtGState".to_string()));
        dict.insert("CA", PdfObject::Real(0.0));
        dict.insert("ca", PdfObject::Real(0.0));
        dict.insert("BM", PdfObject::Name("Multiply".to_string()));

        assert!(
            !ext_g_state_needs_transparent_backdrop(&dict),
            "a fully transparent paint no-op must not allocate a transparent page backdrop"
        );
    }

    #[test]
    fn transparent_page_group_requires_complete_no_paint_blend_state() {
        for (stroke_alpha, fill_alpha) in [
            (Some(0.0), None),
            (None, Some(0.0)),
            (Some(0.0), Some(0.25)),
            (Some(0.25), Some(0.0)),
            (Some(-0.1), Some(0.0)),
        ] {
            let mut dict = PdfDictionary::empty();
            dict.insert("Type", PdfObject::Name("ExtGState".to_string()));
            if let Some(alpha) = stroke_alpha {
                dict.insert("CA", PdfObject::Real(alpha));
            }
            if let Some(alpha) = fill_alpha {
                dict.insert("ca", PdfObject::Real(alpha));
            }
            dict.insert("BM", PdfObject::Name("Multiply".to_string()));

            assert!(
                ext_g_state_needs_transparent_backdrop(&dict),
                "partial or malformed no-paint state must stay conservative: CA={stroke_alpha:?}, ca={fill_alpha:?}"
            );
        }
    }

