    #[test]
    fn transparency_group_form_xobject_offscreen_budget_returns_typed_refusal() {
        let pdf = pdf_with_transparency_group_form_xobject();
        let engine = ContentEngine::open_bytes(pdf).expect("open transparency Form XObject PDF");
        let budget = RenderResourceBudget {
            max_temporary_bytes: 1,
            ..RenderResourceBudget::default()
        };
        let ops = engine.get_page_content(1).expect("page content");
        let viewport = engine
            .page_viewport_for_box(1, 72, PageBox::Media)
            .expect("viewport");
        let resources = engine.get_page_resources(1).expect("page resources");
        let mut state = RenderState::new(
            PixelBuffer::new_filled_with_mode(
                viewport.width_px,
                viewport.height_px,
                WHITE,
                RenderMode::Compat,
            ),
            viewport,
            resources,
            &engine,
            1,
        );
        state.apply_resource_budget(budget);
        state.dispatch_all(&ops);
        let error = state
            .check_fatal_render_error()
            .expect_err("offscreen budget denial must not silently skip a transparency group");

        assert!(
            format!("{error}")
                .contains("transparency Form XObject /Fm0 offscreen surface allocation denied"),
            "unexpected error: {error}"
        );
    }

