    #[test]
    fn cached_display_list_annotation_replay_honors_contract_policies() {
        let pdf = pdf_with_annotation_appearance(0, true, false);
        let engine = ContentEngine::open_bytes(pdf).expect("open annotation appearance PDF");
        let list = PageRenderer::build_display_list(&engine, 1, 72).expect("build display list");
        let mut cache = RenderDocumentCache::new();

        let annotations_excluded =
            PageRenderer::render_display_list_cancellable_with_contract_policies_and_cache(
                &engine,
                1,
                72,
                &list,
                &CancelToken::none(),
                RenderMode::Compat,
                PrintProfile::Display,
                AnnotationRenderPolicy::Exclude,
                FormRenderPolicy::Include,
                &mut cache,
            )
            .expect("render with annotations excluded");
        assert_eq!(
            count_red_pixels(&annotations_excluded),
            0,
            "contract annotations=Exclude must skip annotation appearance replay"
        );
        assert_eq!(
            cache.annotation_appearance_program_entries(),
            0,
            "excluded annotations should not populate appearance programs"
        );

        let forms_excluded =
            PageRenderer::render_display_list_cancellable_with_contract_policies_and_cache(
                &engine,
                1,
                72,
                &list,
                &CancelToken::none(),
                RenderMode::Compat,
                PrintProfile::Display,
                AnnotationRenderPolicy::Include,
                FormRenderPolicy::Exclude,
                &mut cache,
            )
            .expect("render with forms excluded");
        assert_eq!(
            count_red_pixels(&forms_excluded),
            0,
            "contract forms=Exclude must skip widget annotation appearances"
        );
        assert_eq!(
            cache.annotation_appearance_program_entries(),
            0,
            "excluded widgets should not populate appearance programs"
        );

        let included =
            PageRenderer::render_display_list_cancellable_with_contract_policies_and_cache(
                &engine,
                1,
                72,
                &list,
                &CancelToken::none(),
                RenderMode::Compat,
                PrintProfile::Display,
                AnnotationRenderPolicy::Include,
                FormRenderPolicy::Include,
                &mut cache,
            )
            .expect("render with annotations/forms included");
        assert!(
            count_red_pixels(&included) > 100,
            "include policies should render the widget appearance even after excluded renders"
        );
        assert_eq!(cache.annotation_appearance_program_entries(), 1);
    }

