    #[test]
    fn bounded_form_xobject_records_transitive_resource_tile_dependency() {
        let pdf = pdf_with_form_xobject_image_resource();
        let engine = ContentEngine::open_bytes(pdf).expect("open Form XObject image PDF");
        let resources = engine.get_page_resources(1).expect("page resources");
        let list = PageRenderer::build_display_list(&engine, 1, 72).expect("display list");
        let first_form_bounds = list
            .ops
            .iter()
            .find_map(|op| match op {
                DisplayOp::NativeFormXObject {
                    bounds: Some(bounds),
                    ..
                } => Some(*bounds),
                _ => None,
            })
            .expect("Form XObject op has retained bounds");
        let inside_tile = RenderTile {
            x: first_form_bounds.x0.max(0) as u32,
            y: first_form_bounds.y0.max(0) as u32,
            width: 2,
            height: 2,
        };
        let outside_tile = RenderTile {
            x: 75,
            y: 0,
            width: 5,
            height: 5,
        };
        assert!(first_form_bounds.intersects_tile(inside_tile));
        assert!(list.ops.iter().all(|op| {
            !matches!(op, DisplayOp::NativeFormXObject { .. })
                || !op
                    .bounds()
                    .is_some_and(|bounds| bounds.intersects_tile(outside_tile))
        }));

        let mut cache = RenderDocumentCache::new();
        let outside_count = PageRenderer::record_display_list_tile_resource_dependencies(
            &engine,
            1,
            &resources,
            &list,
            outside_tile,
            &mut cache,
        );
        let inside_count = PageRenderer::record_display_list_tile_resource_dependencies(
            &engine,
            1,
            &resources,
            &list,
            inside_tile,
            &mut cache,
        );
        let parent_form_key = form_xobject_program_cache_key(5, 0, 1, "contract:a", 0x1111);
        cache
            .form_xobject_program_cache
            .insert(parent_form_key.clone(), None);
        let next_revision = RevisionId(engine.canonical_document().revision().0.wrapping_add(1));
        let result = engine.invalidate_for_transaction(
            &mut cache,
            &["6 0 R".to_string()],
            &[],
            next_revision,
        );

        assert_eq!(outside_count, 0);
        assert_eq!(inside_count, 2);
        assert!(result.invalidation.invalidated_pages.is_empty());
        assert_eq!(
            result.invalidation.invalidated_tiles,
            vec![(1, inside_tile)]
        );
        assert!(!cache
            .form_xobject_program_cache
            .contains_key(&parent_form_key));
        assert!(!result.invalidation.cache_must_reset);
    }

