    fn alpha_smask_backdrop_transfer_rejects_empty_function_output() {
        use std::collections::BTreeMap;

        let mut tr = BTreeMap::new();
        tr.insert("FunctionType".to_string(), PdfObject::Integer(2));
        tr.insert(
            "C0".to_string(),
            PdfObject::Array(vec![PdfObject::Real(0.5)]),
        );
        tr.insert(
            "C1".to_string(),
            PdfObject::Array(vec![PdfObject::Real(1.0)]),
        );
        tr.insert("N".to_string(), PdfObject::Real(1.0));
        tr.insert(
            "Range".to_string(),
            PdfObject::Array(vec![PdfObject::Real(0.0), PdfObject::Real(1.0)]),
        );

        let mut smask = BTreeMap::new();
        smask.insert(
            "BC".to_string(),
            PdfObject::Array(vec![PdfObject::Real(1.0)]),
        );
        smask.insert(
            "TR".to_string(),
            PdfObject::Dictionary(PdfDictionary::new(tr)),
        );
        let smask = PdfDictionary::new(smask);
        let reader =
            crate::reader::PdfReader::from_bytes(crate::render::shading::tests_minimal_pdf())
                .expect("minimal PDF reader");

        let err = alpha_smask_uses_opaque_bc_backdrop(&smask, &reader)
            .expect_err("malformed /TR must not be treated as TR(0)=0");

        assert!(matches!(err, WellfriendError::UnsupportedFeature(_)));
        assert!(
            format!("{err}").contains("unsupported or malformed SMask /TR function"),
            "unexpected SMask /TR error: {err}"
        );
    }

