    #[test]
    fn synthesized_annotation_helpers_reject_malformed_metadata_locally() {
        let rect = [20.0, 30.0, 80.0, 50.0];

        let mut malformed_quad = PdfDictionary::empty();
        malformed_quad.insert(
            "QuadPoints",
            PdfObject::Array(vec![
                PdfObject::Integer(20),
                PdfObject::Integer(50),
                PdfObject::Name("Bad".to_string()),
                PdfObject::Integer(50),
                PdfObject::Integer(20),
                PdfObject::Integer(30),
                PdfObject::Integer(80),
                PdfObject::Integer(30),
            ]),
        );
        assert!(annotation_local_quad_bounds(&malformed_quad, rect, 60.0, 20.0).is_none());

        let mut malformed_ink = PdfDictionary::empty();
        malformed_ink.insert(
            "InkList",
            PdfObject::Array(vec![PdfObject::Array(vec![
                PdfObject::Integer(20),
                PdfObject::Integer(20),
                PdfObject::Name("Bad".to_string()),
                PdfObject::Integer(80),
            ])]),
        );
        let mut content = String::new();
        assert!(
            append_ink_annotation_paths(&mut content, &malformed_ink, rect, (0.0, 0.0, 0.0))
                .is_none()
        );
        assert!(content.is_empty());

        let mut malformed_color = PdfDictionary::empty();
        malformed_color.insert(
            "C",
            PdfObject::Array(vec![
                PdfObject::Real(1.25),
                PdfObject::Real(0.0),
                PdfObject::Real(0.0),
            ]),
        );
        assert!(annotation_rgb(&malformed_color).is_none());

        let mut malformed_opacity = PdfDictionary::empty();
        malformed_opacity.insert("CA", PdfObject::Real(1.5));
        assert!(annotation_opacity(&malformed_opacity, 1.0).is_none());

        let mut malformed_line = PdfDictionary::empty();
        malformed_line.insert("Subtype", PdfObject::Name("Line".to_string()));
        malformed_line.insert(
            "L",
            PdfObject::Array(vec![
                PdfObject::Integer(20),
                PdfObject::Integer(20),
                PdfObject::Integer(80),
                PdfObject::Integer(80),
                PdfObject::Integer(90),
            ]),
        );
        assert!(
            synthesize_markup_annotation_appearance(&malformed_line, rect, 60.0, 20.0).is_none()
        );

        let mut malformed_freetext = PdfDictionary::empty();
        malformed_freetext.insert("Subtype", PdfObject::Name("FreeText".to_string()));
        malformed_freetext.insert("Contents", PdfObject::String(b"Hello".to_vec()));
        malformed_freetext.insert("Q", PdfObject::Name("Bad".to_string()));
        assert!(
            synthesize_markup_annotation_appearance(&malformed_freetext, rect, 60.0, 20.0)
                .is_none()
        );
    }

