    #[test]
    fn image_smask_shared_source_window_allows_guarded_ccitt_main_image() {
        fn image_ref(
            filter: &[&str],
            color_space: &str,
            is_inline: bool,
            is_mask: bool,
            is_smask: bool,
        ) -> ImageReference {
            ImageReference {
                page_number: 1,
                xobject_name: "Im1".to_string(),
                object_number: 5,
                generation_number: 0,
                width: 16,
                height: 8,
                bits_per_component: 1,
                color_space: color_space.to_string(),
                filter: filter.iter().map(|filter| (*filter).to_string()).collect(),
                is_inline,
                is_mask,
                is_smask,
                inline_data: None,
            }
        }

        assert!(image_reference_supports_shared_smask_source_window(
            &image_ref(&["CCITTFaxDecode"], "DeviceGray", false, false, false)
        ));
        assert!(image_reference_supports_shared_smask_source_window(
            &image_ref(&["FlateDecode", "CCF"], "G", false, false, false)
        ));
        assert!(image_reference_supports_shared_smask_source_window(
            &ImageReference {
                filter: vec![],
                bits_per_component: 8,
                color_space: "DeviceRGB".to_string(),
                ..image_ref(&["CCITTFaxDecode"], "DeviceGray", false, false, false)
            }
        ));

        assert!(!image_reference_supports_shared_smask_source_window(
            &image_ref(
                &["VendorDecode", "CCITTFaxDecode"],
                "DeviceGray",
                false,
                false,
                false
            )
        ));
        assert!(!image_reference_supports_shared_smask_source_window(
            &image_ref(&["CCITTFaxDecode"], "DeviceRGB", false, false, false)
        ));
        assert!(!image_reference_supports_shared_smask_source_window(
            &image_ref(&["CCITTFaxDecode"], "DeviceGray", true, false, false)
        ));
        assert!(!image_reference_supports_shared_smask_source_window(
            &image_ref(&["CCITTFaxDecode"], "DeviceGray", false, true, false)
        ));
        assert!(!image_reference_supports_shared_smask_source_window(
            &image_ref(&["CCITTFaxDecode"], "DeviceGray", false, false, true)
        ));
    }

