    #[test]
    fn packed_plan_restore_restores_pre_resolved_active_font_resource() {
        let engine =
            ContentEngine::open_bytes(simple_vector_pdf("")).expect("open blank packed-font PDF");
        let mut state = blank_render_state(&engine);
        let viewport = state.viewport.clone();
        let mut adapter = RenderStatePlanAdapter {
            state: &mut state,
            viewport_ref: &viewport,
            vector_ctm_base: None,
            forced_vector_color: None,
            forced_vector_fill_pixel_color: None,
            forced_vector_stroke_pixel_color: None,
            ignore_bounds: true,
        };
        let mut f1 = PdfDictionary::empty();
        f1.insert("Subtype", PdfObject::Name("Type1".to_string()));
        f1.insert("BaseFont", PdfObject::Name("Helvetica".to_string()));
        let mut f2 = PdfDictionary::empty();
        f2.insert("Subtype", PdfObject::Name("Type1".to_string()));
        f2.insert("BaseFont", PdfObject::Name("Courier".to_string()));

        adapter.dispatch_state(&GraphicsStateDescriptor::SetFont {
            name: "F1".to_string(),
            size: 10.0,
            dict: Some(f1),
        });
        adapter.dispatch_save();
        adapter.dispatch_state(&GraphicsStateDescriptor::SetFont {
            name: "F2".to_string(),
            size: 12.0,
            dict: Some(f2),
        });
        adapter.dispatch_restore();

        adapter
            .state
            .check_fatal_render_error()
            .expect("packed font restore should not report fatal error");
        let active = adapter
            .state
            .active_font_resource
            .as_ref()
            .expect("restored packed font resource");
        assert_eq!(active.name, "F1");
        assert_eq!(adapter.state.gs.text.font_name, "F1");
        assert_eq!(adapter.state.gs.text.font_size, 10.0);
    }

