    #[test]
    fn packed_plan_replay_refuses_unresolved_state_resource_descriptors() {
        let engine = ContentEngine::open_bytes(simple_vector_pdf(""))
            .expect("open blank packed-state-resource PDF");

        macro_rules! assert_state_refusal {
            ($descriptor:expr, $expected:literal) => {{
                let mut state = blank_render_state(&engine);
                let viewport = state.viewport.clone();
                let mut adapter = RenderStatePlanAdapter {
                    state: &mut state,
                    viewport_ref: &viewport,
                    vector_ctm_base: None,
                    forced_vector_color: None,
                    forced_vector_fill_pixel_color: None,
                    forced_vector_stroke_pixel_color: None,
                    ignore_bounds: true,
                };
                adapter.dispatch_state(&$descriptor);
                let error = adapter
                    .state
                    .check_fatal_render_error()
                    .expect_err("packed state replay must require pre-resolved resources");
                assert!(format!("{error}").contains($expected), "got {error}");
            }};
        }

        assert_state_refusal!(
            GraphicsStateDescriptor::SetFont {
                name: "F1".to_string(),
                size: 12.0,
                dict: None,
            },
            "packed font /F1 missing pre-resolved dictionary"
        );
        let mut ext_g_state_font = PdfDictionary::empty();
        ext_g_state_font.insert(
            "Font",
            PdfObject::Array(vec![
                PdfObject::Name("F1".to_string()),
                PdfObject::Real(12.0),
            ]),
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::ApplyExtGState {
                name: "GSFont".to_string(),
                dict: Some(ext_g_state_font),
                font: None,
            },
            "packed ExtGState /GSFont font /F1 missing pre-resolved dictionary"
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::SetFillColorSpace {
                name: "CS1".to_string(),
                object: None,
            },
            "packed fill color-space /CS1 missing pre-resolved resource object"
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::SetStrokeColorSpace {
                name: "CS1".to_string(),
                object: None,
            },
            "packed stroke color-space /CS1 missing pre-resolved resource object"
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::SetFillColor {
                components: Vec::new(),
                name: Some("P1".to_string()),
                pattern: None,
            },
            "packed fill pattern /P1 missing pre-resolved resource object"
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::SetStrokeColor {
                components: Vec::new(),
                name: Some("P1".to_string()),
                pattern: None,
            },
            "packed stroke pattern /P1 missing pre-resolved resource object"
        );
        assert_state_refusal!(
            GraphicsStateDescriptor::BeginMarkedContentWithProperties {
                tag: "OC".to_string(),
                properties: MarkedContentProperties::Name {
                    name: "Layer1".to_string(),
                    object: None,
                },
            },
            "packed marked-content Properties /Layer1 missing pre-resolved resource object"
        );

        let mut state = blank_render_state(&engine);
        let viewport = state.viewport.clone();
        let mut adapter = RenderStatePlanAdapter {
            state: &mut state,
            viewport_ref: &viewport,
            vector_ctm_base: None,
            forced_vector_color: None,
            forced_vector_fill_pixel_color: None,
            forced_vector_stroke_pixel_color: None,
            ignore_bounds: true,
        };
        adapter.dispatch_state(&GraphicsStateDescriptor::SetFillColorSpace {
            name: "DeviceRGB".to_string(),
            object: None,
        });
        adapter
            .state
            .check_fatal_render_error()
            .expect("built-in color spaces do not need pre-resolved resources");
        assert_eq!(adapter.state.gs.fill_color_space, ColorSpace::DeviceRGB);
    }

    #[test]
    fn packed_culled_text_array_advances_text_state_without_painting() {
        let engine = ContentEngine::open_bytes(simple_vector_pdf(""))
            .expect("open blank packed-text-culling PDF");
        let outside_bounds = RenderBounds {
            x0: 100,
            y0: 100,
            x1: 110,
            y1: 110,
        };

        let mut expected = blank_render_state(&engine);
        install_helvetica_text_state(&mut expected, 12.0);
        expected.render_text_string(b"A B");
        expected.adjust_text_position(-120.0);
        expected.render_text_string(b"C");
        expected
            .check_fatal_render_error()
            .expect("direct text advancement must stay valid");

        let mut actual = blank_render_state(&engine);
        install_helvetica_text_state(&mut actual, 12.0);
        {
            let viewport = actual.viewport.clone();
            let mut adapter = RenderStatePlanAdapter {
                state: &mut actual,
                viewport_ref: &viewport,
                vector_ctm_base: None,
                forced_vector_color: None,
                forced_vector_fill_pixel_color: None,
                forced_vector_stroke_pixel_color: None,
                ignore_bounds: false,
            };
            adapter.dispatch_text(
                &TextDescriptor::ShowArray(vec![
                    TextArrayItem::Bytes(b"A B".to_vec()),
                    TextArrayItem::Adjustment(-120.0),
                    TextArrayItem::Bytes(b"C".to_vec()),
                ]),
                Some(&outside_bounds),
            );
            adapter
                .state
                .check_fatal_render_error()
                .expect("culled packed text advancement must stay valid");
        }

        assert_eq!(actual.gs.text.tm, expected.gs.text.tm);
    }

