    #[test]
    fn empty_path_clip_installs_empty_clip() {
        let engine = ContentEngine::open_bytes(simple_vector_pdf(""))
            .expect("open blank clipping sequence PDF");

        let mut empty_path_state = blank_render_state(&engine);
        empty_path_state.dispatch_all(&[
            ContentOperation::new("W", Vec::new()),
            ContentOperation::new("n", Vec::new()),
        ]);
        empty_path_state
            .check_fatal_render_error()
            .expect("empty clipping path is valid and should clip out subsequent paint");
        assert!(empty_path_state
            .buf
            .clip_mask()
            .is_some_and(ClipMask::is_empty));

        let mut move_only_state = blank_render_state(&engine);
        move_only_state.dispatch_all(&[
            ContentOperation::new("m", vec![Operand::Real(0.0), Operand::Real(0.0)]),
            ContentOperation::new("W", Vec::new()),
            ContentOperation::new("n", Vec::new()),
        ]);
        move_only_state
            .check_fatal_render_error()
            .expect("move-only clipping path is valid and should clip out subsequent paint");
        assert!(move_only_state
            .buf
            .clip_mask()
            .is_some_and(ClipMask::is_empty));
    }

