    #[test]
    fn type3_retained_plan_accepts_mixed_path_resource_charproc_with_inherited_color() {
        let charproc = type3_mixed_path_image_charproc();
        let ops =
            crate::content::ContentParser::parse(charproc.as_bytes()).expect("parse Type3 ops");
        let mut resources = PageResources::default();
        resources.xobjects.insert("Im1".to_string(), (6, 0));
        resources
            .xobject_subtypes
            .insert("Im1".to_string(), "Image".to_string());
        let viewport = Viewport::new([0.0, 0.0, 100.0, 100.0], 72);
        let list = build_display_list(&ops, viewport.clone(), &resources);

        assert!(list.is_fully_supported());
        assert!(type3_charproc_display_list_is_retained_supported(&list));
        assert!(list
            .ops
            .iter()
            .any(|op| matches!(op, DisplayOp::FillPath { .. })));
        assert!(list
            .ops
            .iter()
            .any(|op| matches!(op, DisplayOp::NativeImageXObject { .. })));
        assert_eq!(
            type3_charproc_retained_path_color_policy(&ops, &list),
            Type3RetainedPathColorPolicy::InheritAll
        );

        let contract = RenderContract::for_viewport(
            RevisionId(1),
            ObjectIdentityId(1),
            1,
            &viewport,
            RenderTile::full(viewport.width_px, viewport.height_px),
            RenderMode::HighQuality,
        );
        let plan =
            RenderPlan::compile_with_resources(list, contract, &resources).expect("compile plan");
        assert!(plan.packed.has_only_supported_descriptors());
    }

