    #[test]
    fn synthesized_widget_helpers_reject_malformed_metadata_locally() {
        let engine = ContentEngine::open_bytes(pdf_with_form_objects(vec![], "", "", ""))
            .expect("open widget helper context PDF");
        let reader = engine.document().reader();
        let rect = [0.0, 0.0, 80.0, 30.0];

        let mut malformed_da = PdfDictionary::empty();
        malformed_da.insert("Subtype", PdfObject::Name("Widget".to_string()));
        malformed_da.insert("FT", PdfObject::Name("Tx".to_string()));
        malformed_da.insert("V", PdfObject::String(b"Hello".to_vec()));
        malformed_da.insert("DA", PdfObject::String(b"/F1 12 Tf 1.5 0 0 rg".to_vec()));

        assert!(parse_default_appearance(b"/F1 12 Tf 1.5 0 0 rg").is_none());
        assert!(synthesize_annotation_appearance(&malformed_da, reader, &engine, rect).is_none());

        let mut mk = PdfDictionary::empty();
        mk.insert(
            "BG",
            PdfObject::Array(vec![
                PdfObject::Real(1.5),
                PdfObject::Real(0.0),
                PdfObject::Real(0.0),
            ]),
        );
        mk.insert("CA", PdfObject::String(b"Go".to_vec()));

        let mut malformed_mk = PdfDictionary::empty();
        malformed_mk.insert("Subtype", PdfObject::Name("Widget".to_string()));
        malformed_mk.insert("FT", PdfObject::Name("Btn".to_string()));
        malformed_mk.insert("Ff", PdfObject::Integer(FIELD_FLAG_PUSHBUTTON));
        malformed_mk.insert("MK", PdfObject::Dictionary(mk.clone()));

        assert!(mk_rgb(Some(&mk), "BG").is_none());
        assert!(synthesize_annotation_appearance(&malformed_mk, reader, &engine, rect).is_none());
    }

