    #[test]
    fn annotation_display_text_refuses_nonfinite_or_filtered_array_values() {
        for value in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
            let object = PdfObject::Real(value);
            assert!(
                strict_display_text_object(&object, "malformed display text").is_err(),
                "strict display text must reject non-finite numbers"
            );
            assert!(
                display_text_from_object(&object).is_none(),
                "non-strict display text must not serialize non-finite numbers as zero"
            );
        }

        let malformed_array = PdfObject::Array(vec![
            PdfObject::String(b"kept".to_vec()),
            PdfObject::Dictionary(PdfDictionary::empty()),
        ]);
        assert!(
            strict_display_text_object(&malformed_array, "malformed display text").is_err(),
            "strict display text must reject malformed array members"
        );
        assert!(
            display_text_from_object(&malformed_array).is_none(),
            "display text arrays must not silently filter malformed members"
        );

        let off_array = PdfObject::Array(vec![
            PdfObject::String(b"kept".to_vec()),
            PdfObject::Name("Off".to_string()),
        ]);
        let (text, bytes) = display_text_from_object(&off_array)
            .expect("explicit /Off array member remains the accepted empty value");
        assert_eq!(text, "kept");
        assert_eq!(bytes, b"kept");
    }

