    #[test]
    fn source_scoped_font_cache_pruning_uses_source_reference_markers() {
        let mut cache = RenderDocumentCache::new();
        cache.remember_source_cache_markers(
            ObjectIdentityId(4),
            source_cache_markers_for_object(10, 0),
        );
        let stale_key = "F1:stale:font:ref:10:0:".to_string();
        let retained_key = "F1:retained:font:ref:99:0:".to_string();
        insert_font_bytes_cache_entry(
            &mut cache.font_bytes_cache,
            &mut cache.font_bytes_cache_order,
            &mut cache.font_bytes_cache_bytes,
            &mut cache.font_bytes_cache_stats,
            stale_key.clone(),
            Some(Arc::new(vec![1, 2, 3])),
        );
        insert_font_bytes_cache_entry(
            &mut cache.font_bytes_cache,
            &mut cache.font_bytes_cache_order,
            &mut cache.font_bytes_cache_bytes,
            &mut cache.font_bytes_cache_stats,
            retained_key.clone(),
            Some(Arc::new(vec![4, 5, 6])),
        );

        cache.prune_source_scoped_artifact_caches(&[ObjectIdentityId(4)]);

        assert!(!cache.font_bytes_cache.contains_key(&stale_key));
        assert!(cache.font_bytes_cache.contains_key(&retained_key));
        assert_eq!(cache.font_bytes_cache_stats().evictions, 1);
    }

