    fn sample_type3_geometry(cache_key: &str) -> Arc<Type3GlyphGeometry> {
        let mut fill_path = Path::new();
        fill_path.rect(0.0, 0.0, 10.0, 10.0);
        let mut stroke_path = Path::new();
        stroke_path.move_to(0.0, 0.0);
        stroke_path.line_to(10.0, 10.0);

        Arc::new(Type3GlyphGeometry {
            cache_key: cache_key.to_string(),
            fills: vec![Type3Fill {
                path: fill_path,
                rule: FillRule::NonZero,
                color: Some(BLACK),
            }],
            strokes: vec![Type3Stroke {
                path: stroke_path,
                width: 1.0,
                dash: DashState::new(vec![2.0, 1.0], 0.0),
                cap: LineCap::Butt,
                join: LineJoin::Miter,
                miter_limit: 10.0,
                color: Some(BLACK),
            }],
            advance_width: Some(500.0),
            _uses_color_state: true,
        })
    }

    #[test]
    fn type3_program_caches_report_byte_accounting() {
        let mut charproc_cache = Type3ProgramCache::<Type3CharProc>::default();
        charproc_cache.insert("charproc-a".to_string(), Some(sample_type3_charproc()));
        assert!(charproc_cache.bytes() > 0);
        assert_eq!(charproc_cache.stats().bytes, charproc_cache.bytes());
        assert_eq!(
            charproc_cache.oldest_entry_bytes(),
            Some(charproc_cache.bytes())
        );

        let mut geometry_cache = Type3ProgramCache::<Type3GlyphGeometry>::default();
        geometry_cache.insert(
            "geometry-a".to_string(),
            Some(sample_type3_geometry("geometry-a")),
        );
        assert!(geometry_cache.bytes() > 0);
        assert_eq!(geometry_cache.stats().bytes, geometry_cache.bytes());
        assert_eq!(
            geometry_cache.oldest_entry_bytes(),
            Some(geometry_cache.bytes())
        );

        let mut retained_cache = Type3ProgramCache::<Type3RetainedCharProcPlan>::default();
        retained_cache.insert("retained-a".to_string(), Some(sample_type3_retained_plan()));
        assert!(retained_cache.bytes() > 0);
        assert_eq!(retained_cache.stats().bytes, retained_cache.bytes());
        assert_eq!(
            retained_cache.oldest_entry_bytes(),
            Some(retained_cache.bytes())
        );
    }

    #[test]
    fn type3_program_cache_tracks_explicit_lifecycle_states() {
        let mut charproc_cache = Type3ProgramCache::<Type3CharProc>::default();
        assert_eq!(
            charproc_cache.lifecycle("charproc-a"),
            Type3ProgramLifecycle::Unvisited
        );

        charproc_cache.insert_compiling("charproc-a".to_string());
        assert_eq!(
            charproc_cache.lifecycle("charproc-a"),
            Type3ProgramLifecycle::Compiling
        );
        assert!(matches!(charproc_cache.get("charproc-a"), Some(None)));

        charproc_cache.insert("charproc-a".to_string(), Some(sample_type3_charproc()));
        assert_eq!(
            charproc_cache.lifecycle("charproc-a"),
            Type3ProgramLifecycle::Compiled
        );
        assert!(matches!(charproc_cache.get("charproc-a"), Some(Some(_))));

        charproc_cache.insert_failed("charproc-a".to_string(), "decode failed");
        assert_eq!(
            charproc_cache.lifecycle("charproc-a"),
            Type3ProgramLifecycle::Failed
        );
        assert_eq!(
            charproc_cache.failure_reason("charproc-a"),
            Some("decode failed")
        );
        assert!(matches!(charproc_cache.get("charproc-a"), Some(None)));
    }

    #[test]
    fn render_document_cache_budget_evicts_type3_parsed_program_caches() {
        let mut cache = RenderDocumentCache::new();
        cache
            .type3_charproc_cache
            .insert("charproc-a".to_string(), Some(sample_type3_charproc()));
        cache.type3_geometry_cache.insert(
            "geometry-a".to_string(),
            Some(sample_type3_geometry("geometry-a")),
        );
        cache
            .type3_retained_charproc_cache
            .insert("retained-a".to_string(), Some(sample_type3_retained_plan()));

        assert!(cache.aggregate_resource_cache_bytes() > 0);
        assert!(cache.type3_charproc_program_cache_stats().bytes > 0);
        assert!(cache.type3_geometry_program_cache_stats().bytes > 0);
        assert!(cache.type3_retained_charproc_program_cache_stats().bytes > 0);

        cache.enforce_bounded_maps(RenderResourceBudget {
            max_cache_bytes: 0,
            ..RenderResourceBudget::default()
        });

        assert_eq!(cache.aggregate_resource_cache_bytes(), 0);
        assert_eq!(cache.type3_charproc_program_cache_stats().entries, 0);
        assert_eq!(cache.type3_geometry_program_cache_stats().entries, 0);
        assert_eq!(
            cache.type3_retained_charproc_program_cache_stats().entries,
            0
        );
        assert_eq!(cache.type3_charproc_program_cache_stats().evictions, 1);
        assert_eq!(cache.type3_geometry_program_cache_stats().evictions, 1);
        assert_eq!(
            cache
                .type3_retained_charproc_program_cache_stats()
                .evictions,
            1
        );
    }

    #[test]
    fn type3_retained_charproc_plan_cache_key_includes_contract_resources_and_source() {
        let viewport = Viewport::new([0.0, 0.0, 10.0, 10.0], 72);
        let display_contract = RenderContract::for_viewport(
            RevisionId(1),
            ObjectIdentityId(1),
            1,
            &viewport,
            RenderTile::full(viewport.width_px, viewport.height_px),
            RenderMode::Compat,
        );
        let mut print_contract = display_contract.clone();
        print_contract.print_profile = PrintProfile::Print;

        let base = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            0x1111,
            &display_contract.cache_fingerprint(),
            Some("type3-retained:15:0:"),
        );
        let other_resources = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            0x2222,
            &display_contract.cache_fingerprint(),
            Some("type3-retained:15:0:"),
        );
        let other_contract = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            0x1111,
            &print_contract.cache_fingerprint(),
            Some("type3-retained:15:0:"),
        );
        let other_source = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            0x1111,
            &display_contract.cache_fingerprint(),
            Some("type3-retained:16:0:"),
        );

        assert!(base.contains("type3-retained:15:0:"));
        assert_ne!(base, other_resources);
        assert_ne!(base, other_contract);
        assert_ne!(base, other_source);
    }

