    #[test]
    fn cached_type3_retained_charproc_plan_reuses_compiled_plan() {
        let engine =
            ContentEngine::open_bytes(simple_vector_pdf("")).expect("open blank Type3 cache PDF");
        let mut state = blank_render_state(&engine);
        let resources = PageResources::default();
        let contract = state
            .current_retained_plan_contract()
            .expect("retained plan contract");
        let charproc = sample_retained_type3_charproc();
        let cache_key = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            page_resources_fingerprint(&resources),
            &contract.cache_fingerprint(),
            Some("type3-retained:15:0:"),
        );

        let first = state
            .cached_type3_retained_charproc_plan(
                "font-a\0A",
                Some("type3-retained:15:0:"),
                charproc.as_ref(),
                &resources,
                contract.clone(),
            )
            .expect("compile retained Type3 plan");
        let second = state
            .cached_type3_retained_charproc_plan(
                "font-a\0A",
                Some("type3-retained:15:0:"),
                charproc.as_ref(),
                &resources,
                contract,
            )
            .expect("reuse retained Type3 plan");

        assert!(Arc::ptr_eq(&first, &second));
        assert_eq!(
            state.type3_retained_charproc_cache.lifecycle(&cache_key),
            Type3ProgramLifecycle::Compiled
        );
        assert_eq!(state.type3_retained_charproc_cache.stats().hits, 1);
        assert_eq!(state.type3_retained_charproc_cache.stats().misses, 1);
    }

    #[test]
    fn cached_type3_retained_charproc_plan_preserves_refusal_reason() {
        let engine = ContentEngine::open_bytes(simple_vector_pdf(""))
            .expect("open blank Type3 negative-cache PDF");
        let mut state = blank_render_state(&engine);
        let resources = PageResources::default();
        let contract = state
            .current_retained_plan_contract()
            .expect("retained plan contract");
        let charproc = Type3CharProc {
            ops: vec![ContentOperation::new("QQQ", Vec::new())],
            advance_width: None,
            glyph_bbox: None,
        };
        let cache_key = type3_retained_charproc_plan_cache_key(
            "font-a\0A",
            page_resources_fingerprint(&resources),
            &contract.cache_fingerprint(),
            Some("type3-retained:15:0:"),
        );

        let first_err = match state.cached_type3_retained_charproc_plan(
            "font-a\0A",
            Some("type3-retained:15:0:"),
            &charproc,
            &resources,
            contract.clone(),
        ) {
            Ok(_) => panic!("unsupported retained Type3 plan unexpectedly compiled"),
            Err(err) => err,
        };
        let second_err = match state.cached_type3_retained_charproc_plan(
            "font-a\0A",
            Some("type3-retained:15:0:"),
            &charproc,
            &resources,
            contract,
        ) {
            Ok(_) => panic!("unsupported retained Type3 plan unexpectedly compiled from cache"),
            Err(err) => err,
        };

        assert!(first_err.contains("unsupported"));
        assert_eq!(second_err, first_err);
        assert_eq!(
            state.type3_retained_charproc_cache.lifecycle(&cache_key),
            Type3ProgramLifecycle::Failed
        );
        assert_eq!(
            state
                .type3_retained_charproc_cache
                .failure_reason(&cache_key),
            Some(first_err.as_str())
        );
        assert_eq!(state.type3_retained_charproc_cache.stats().hits, 1);
    }

    #[test]
    fn type3_program_caches_evict_lru_negative_entries_without_full_clear() {
        let mut charproc_cache = Type3ProgramCache::<Type3CharProc>::default();
        let hot_charproc = "hot-charproc".to_string();
        charproc_cache.insert(hot_charproc.clone(), None);
        for code in 0..(Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES - 1) {
            charproc_cache.insert(format!("charproc-{code}"), None);
        }
        assert_eq!(
            charproc_cache.len(),
            Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES
        );
        assert!(matches!(charproc_cache.get(&hot_charproc), Some(None)));
        charproc_cache.insert("new-charproc".to_string(), None);
        assert_eq!(
            charproc_cache.len(),
            Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES
        );
        assert!(
            matches!(charproc_cache.get(&hot_charproc), Some(None)),
            "hot negative CharProc cache entry must survive LRU pressure"
        );
        assert!(
            charproc_cache.get("charproc-0").is_none(),
            "oldest cold CharProc cache entry should be evicted first"
        );
        assert_eq!(charproc_cache.stats().evictions, 1);

        let mut geometry_cache = Type3ProgramCache::<Type3GlyphGeometry>::default();
        let hot_geometry = "hot-geometry".to_string();
        geometry_cache.insert(hot_geometry.clone(), None);
        for code in 0..(Type3ProgramCache::<Type3GlyphGeometry>::MAX_ENTRIES - 1) {
            geometry_cache.insert(format!("geometry-{code}"), None);
        }
        assert_eq!(
            geometry_cache.len(),
            Type3ProgramCache::<Type3GlyphGeometry>::MAX_ENTRIES
        );
        assert!(matches!(geometry_cache.get(&hot_geometry), Some(None)));
        geometry_cache.insert("new-geometry".to_string(), None);
        assert_eq!(
            geometry_cache.len(),
            Type3ProgramCache::<Type3GlyphGeometry>::MAX_ENTRIES
        );
        assert!(
            matches!(geometry_cache.get(&hot_geometry), Some(None)),
            "hot negative geometry cache entry must survive LRU pressure"
        );
        assert!(
            geometry_cache.get("geometry-0").is_none(),
            "oldest cold geometry cache entry should be evicted first"
        );
        assert_eq!(geometry_cache.stats().evictions, 1);
    }

    #[test]
    fn type3_program_cache_absorbs_child_through_lru_admission() {
        let mut parent = Type3ProgramCache::<Type3CharProc>::default();
        for code in 0..Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES {
            parent.insert(format!("parent-{code}"), None);
        }
        assert_eq!(
            parent.len(),
            Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES
        );

        let mut child = Type3ProgramCache::<Type3CharProc>::default();
        let child_hot = "child-hot".to_string();
        child.insert(child_hot.clone(), None);
        child.insert("child-cold".to_string(), None);
        assert!(matches!(child.get(&child_hot), Some(None)));

        parent.absorb_from(child);

        assert_eq!(
            parent.len(),
            Type3ProgramCache::<Type3CharProc>::MAX_ENTRIES
        );
        assert!(matches!(parent.get("child-cold"), Some(None)));
        assert!(
            matches!(parent.get(&child_hot), Some(None)),
            "child recency should be preserved when nested render caches are absorbed"
        );
        assert!(
            parent.get("parent-0").is_none(),
            "child cache admission should evict from the old parent LRU frontier"
        );
        assert_eq!(parent.stats().evictions, 2);
    }

