    #[test]
    fn glyph_mask_cache_evicts_lru_without_clearing_hot_masks() {
        fn mask_key(code: u16) -> GlyphMaskCacheKey {
            GlyphMaskCacheKey {
                glyph: GlyphCacheKey {
                    font_hash: 42,
                    variation_hash: 0,
                    code,
                    is_gid: false,
                    color_mode: 0,
                },
                a: 1000,
                b: 0,
                c: 0,
                d: 1000,
                frac_e: 0,
                frac_f: 0,
                hinting: false,
                binary_alpha: false,
            }
        }

        let mut cache = GlyphMaskCache::default();
        let hot = mask_key(60_000);
        let mask =
            Arc::new(RasterizedGlyphMask::from_alpha(0, 0, 1, 1, vec![255]).expect("valid mask"));
        cache.insert(hot.clone(), mask.clone());
        for code in 0..(GlyphMaskCache::MAX_ENTRIES as u16 - 1) {
            cache.insert(mask_key(code), mask.clone());
        }
        assert_eq!(cache.len(), GlyphMaskCache::MAX_ENTRIES);

        assert!(
            cache.get(&hot).is_some(),
            "touching hot mask must refresh recency before pressure"
        );
        cache.insert(mask_key(60_001), mask);

        assert_eq!(cache.len(), GlyphMaskCache::MAX_ENTRIES);
        assert!(
            cache.get(&hot).is_some(),
            "hot glyph mask must survive one-entry LRU eviction"
        );
        assert!(
            cache.get(&mask_key(0)).is_none(),
            "oldest cold glyph mask should be the eviction victim"
        );
        assert_eq!(cache.stats().evictions, 1);
    }

