    #[test]
    fn type3_and_path_mask_caches_evict_lru_without_full_clear() {
        fn type3_mask_key(code: usize) -> Type3MaskCacheKey {
            Type3MaskCacheKey {
                glyph: format!("glyph-{code}"),
                fill_index: 0,
                fill_rule: 1,
                a: 1000,
                b: 0,
                c: 0,
                d: 1000,
                frac_e: 0,
                frac_f: 0,
                binary_alpha: false,
            }
        }

        fn type3_rendered_key(code: usize) -> Type3RenderedGlyphCacheKey {
            Type3RenderedGlyphCacheKey {
                glyph: format!("glyph-{code}"),
                render_mode: 0,
                fill_color: [0, 0, 0, 255],
                stroke_color: [255, 255, 255, 255],
                a: 1000,
                b: 0,
                c: 0,
                d: 1000,
                frac_e: 0,
                frac_f: 0,
                binary_alpha: false,
            }
        }

        fn path_fill_key(code: usize) -> PathFillMaskCacheKey {
            PathFillMaskCacheKey {
                path_hash: code as u64,
                fill_rule: 1,
                flatness: 500,
                a: 1000,
                b: 0,
                c: 0,
                d: 1000,
                frac_e: 0,
                frac_f: 0,
                binary_alpha: false,
            }
        }

        fn path_stroke_key(code: usize) -> PathStrokeMaskCacheKey {
            PathStrokeMaskCacheKey {
                path_hash: code as u64,
                width: 100,
                flatness: 500,
                cap: 0,
                join: 0,
                miter_limit: 1000,
                a: 1000,
                b: 0,
                c: 0,
                d: 1000,
                frac_e: 0,
                frac_f: 0,
                binary_alpha: false,
            }
        }

        let mask =
            Arc::new(RasterizedGlyphMask::from_alpha(0, 0, 1, 1, vec![255]).expect("valid mask"));

        let mut type3_mask_cache = Type3MaskCache::default();
        let hot_type3_mask = type3_mask_key(60_000);
        type3_mask_cache.insert(hot_type3_mask.clone(), mask.clone());
        for code in 0..(Type3MaskCache::MAX_ENTRIES - 1) {
            type3_mask_cache.insert(type3_mask_key(code), mask.clone());
        }
        assert_eq!(type3_mask_cache.len(), Type3MaskCache::MAX_ENTRIES);
        assert!(type3_mask_cache.get(&hot_type3_mask).is_some());
        type3_mask_cache.insert(type3_mask_key(60_001), mask.clone());
        assert_eq!(type3_mask_cache.len(), Type3MaskCache::MAX_ENTRIES);
        assert!(type3_mask_cache.get(&hot_type3_mask).is_some());
        assert!(type3_mask_cache.get(&type3_mask_key(0)).is_none());
        assert_eq!(type3_mask_cache.stats().evictions, 1);

        let mut rendered_cache = Type3RenderedGlyphCache::default();
        let hot_rendered = type3_rendered_key(61_000);
        let rendered = Arc::new(Type3RenderedGlyph {
            x: 0,
            y: 0,
            width: 1,
            height: 1,
            pixels: vec![0, 0, 0, 255],
        });
        rendered_cache.insert(hot_rendered.clone(), rendered.clone());
        for code in 0..(Type3RenderedGlyphCache::MAX_ENTRIES - 1) {
            rendered_cache.insert(type3_rendered_key(code), rendered.clone());
        }
        assert_eq!(rendered_cache.len(), Type3RenderedGlyphCache::MAX_ENTRIES);
        assert!(rendered_cache.get(&hot_rendered).is_some());
        rendered_cache.insert(type3_rendered_key(61_001), rendered);
        assert_eq!(rendered_cache.len(), Type3RenderedGlyphCache::MAX_ENTRIES);
        assert!(rendered_cache.get(&hot_rendered).is_some());
        assert!(rendered_cache.get(&type3_rendered_key(0)).is_none());
        assert_eq!(rendered_cache.stats().evictions, 1);

        let mut path_fill_cache = PathFillMaskCache::default();
        let hot_fill = path_fill_key(62_000);
        path_fill_cache.insert(hot_fill.clone(), mask.clone());
        for code in 0..(PathFillMaskCache::MAX_ENTRIES - 1) {
            path_fill_cache.insert(path_fill_key(code), mask.clone());
        }
        assert_eq!(path_fill_cache.len(), PathFillMaskCache::MAX_ENTRIES);
        assert!(path_fill_cache.get(&hot_fill).is_some());
        path_fill_cache.insert(path_fill_key(62_001), mask.clone());
        assert_eq!(path_fill_cache.len(), PathFillMaskCache::MAX_ENTRIES);
        assert!(path_fill_cache.get(&hot_fill).is_some());
        assert!(path_fill_cache.get(&path_fill_key(0)).is_none());
        assert_eq!(path_fill_cache.stats().evictions, 1);

        let mut path_stroke_cache = PathStrokeMaskCache::default();
        let hot_stroke = path_stroke_key(63_000);
        path_stroke_cache.insert(hot_stroke.clone(), mask.clone());
        for code in 0..(PathStrokeMaskCache::MAX_ENTRIES - 1) {
            path_stroke_cache.insert(path_stroke_key(code), mask.clone());
        }
        assert_eq!(path_stroke_cache.len(), PathStrokeMaskCache::MAX_ENTRIES);
        assert!(path_stroke_cache.get(&hot_stroke).is_some());
        path_stroke_cache.insert(path_stroke_key(63_001), mask);
        assert_eq!(path_stroke_cache.len(), PathStrokeMaskCache::MAX_ENTRIES);
        assert!(path_stroke_cache.get(&hot_stroke).is_some());
        assert!(path_stroke_cache.get(&path_stroke_key(0)).is_none());
        assert_eq!(path_stroke_cache.stats().evictions, 1);
    }

    #[test]
    fn document_font_cache_key_includes_contract_budget_and_font_provider_identity() {
        let mut font = PdfDictionary::empty();
        font.insert("Subtype", PdfObject::Name("Type1".to_string()));
        font.insert("BaseFont", PdfObject::Name("Helvetica".to_string()));

        let base = font_resource_cache_key_for_contract(
            "F1",
            &font,
            "contract:a",
            "registered-fonts:none",
            RenderResourceBudget::default(),
        );
        let other_contract = font_resource_cache_key_for_contract(
            "F1",
            &font,
            "contract:b",
            "registered-fonts:none",
            RenderResourceBudget::default(),
        );
        assert_ne!(
            base, other_contract,
            "font byte/resolver cache identity must not cross render contracts"
        );

        let other_provider = font_resource_cache_key_for_contract(
            "F1",
            &font,
            "contract:a",
            "registered-fonts:1:feedface",
            RenderResourceBudget::default(),
        );
        assert_ne!(
            base, other_provider,
            "font byte/resolver cache identity must not cross registered font-provider revisions"
        );

        let other_budget = font_resource_cache_key_for_contract(
            "F1",
            &font,
            "contract:a",
            "registered-fonts:none",
            RenderResourceBudget {
                max_cache_bytes: 4096,
                ..RenderResourceBudget::default()
            },
        );
        assert_ne!(
            base, other_budget,
            "font byte/resolver cache identity must include resource budget"
        );
    }

