    #[test]
    fn clip_mask_from_path_evenodd_nested_rects() {
        let vp = Viewport::new([0.0, 0.0, 100.0, 100.0], 72);
        let ctm = Transform2D::identity();
        let mut path = Path::new();
        path.rect(10.0, 10.0, 80.0, 80.0);
        path.rect(30.0, 30.0, 40.0, 40.0);
        let flat = flatten_path(&path, &ctm, &vp, 0.5);
        let clip_eo = ClipMask::from_path(&flat, 100, 100, FillRule::EvenOdd);
        let clip_nz = ClipMask::from_path(&flat, 100, 100, FillRule::NonZero);
        assert!(!clip_eo.is_visible(50, 50));
        assert!(clip_nz.is_visible(50, 50));
    }

    #[test]
    fn clip_is_preserved_across_simple_paint_operations() {
        let mut buf = PixelBuffer::new_filled(100, 100, WHITE);
        let mut clip = ClipMask::all_visible(100, 100);
        clip.fill_rect(50, 0, 50, 100, false);
        buf.set_clip(clip);
        buf.fill_rect(0, 0, 100, 100, RED);
        assert_eq!(buf.get_pixel(25, 50), RED);
        assert_eq!(buf.get_pixel(75, 50), WHITE);
    }

    #[test]
    fn set_clip_intersects_with_existing_clip() {
        let mut buf = PixelBuffer::new_filled(10, 10, WHITE);
        let mut clip1 = ClipMask::all_visible(10, 10);
        clip1.fill_rect(5, 0, 5, 10, false);
        buf.set_clip(clip1);
        let mut clip2 = ClipMask::all_visible(10, 10);
        clip2.fill_rect(0, 5, 10, 5, false);
        buf.set_clip(clip2);
        let clip = buf.clip_mask().expect("clip should be installed");
        assert!(clip.is_visible(2, 2));
        assert!(!clip.is_visible(7, 2));
        assert!(!clip.is_visible(2, 7));
        assert!(!clip.is_visible(7, 7));
    }

    #[test]
    fn restore_clip_from_dag_node_preserves_unmaterialized_saved_state() {
        let dense_mask = ClipMask::from_alpha_bytes(3, 1, vec![0, 128, 255]);
        let sparse_mask = ClipMask::from_visible_runs(3, 1, vec![vec![(1, 3)]]);
        let mut dag = ClipDag::new();
        let dense = dag.intern_mask(&dense_mask);
        let sparse = dag.intern_mask(&sparse_mask);
        let composite = dag.intersect(&dense, &sparse);
        let mut buf = PixelBuffer::new_filled(3, 1, WHITE);

        restore_buffer_clip_from_node(&mut buf, &composite);

        let restored = buf.clip_mask().expect("restored clip");
        assert_eq!(restored.opacity_byte(0, 0), 0);
        assert_eq!(restored.opacity_byte(1, 0), 128);
        assert_eq!(restored.opacity_byte(2, 0), 255);
        assert!(!composite.is_materialized());
        assert!(!dense.is_materialized());
        assert!(!sparse.is_materialized());
    }

    #[test]
    fn q_restore_restores_previous_clip_mask() {
        let engine = ContentEngine::open_path(fixture("flate.pdf")).expect("open flate fixture");
        let viewport = Viewport::new([0.0, 0.0, 10.0, 10.0], 72);
        let mut buf = PixelBuffer::new_filled(10, 10, WHITE);
        let mut left_clip = ClipMask::all_visible(10, 10);
        left_clip.fill_rect(5, 0, 5, 10, false);
        buf.set_clip(left_clip);

        let mut state = RenderState::new(buf, viewport, PageResources::default(), &engine, 1);
        state.dispatch(&ContentOperation::new("q", Vec::new()));
        let saved_node = Arc::clone(
            state
                .clip_stack
                .last()
                .expect("q should save the active clip node"),
        );
        assert!(Arc::ptr_eq(&saved_node, &state.current_clip));

        let mut top_clip = ClipMask::all_visible(10, 10);
        top_clip.fill_rect(0, 5, 10, 5, false);
        state.apply_clip_mask_node(top_clip);
        assert!(!Arc::ptr_eq(&saved_node, &state.current_clip));
        state.dispatch(&ContentOperation::new("Q", Vec::new()));
        assert!(Arc::ptr_eq(&saved_node, &state.current_clip));

        let clip = state.buf.clip_mask().expect("clip should be restored");
        assert!(
            clip.is_visible(2, 7),
            "left clip should restore bottom-left visibility"
        );
        assert!(
            !clip.is_visible(7, 2),
            "left clip should keep right side clipped"
        );
    }

    #[test]
    fn content_path_clip_replay_reuses_transformed_clip_node_cache() {
        let engine = ContentEngine::open_path(fixture("flate.pdf")).expect("open flate fixture");
        let viewport = Viewport::new([0.0, 0.0, 10.0, 10.0], 72);
        let buf = PixelBuffer::new_filled(10, 10, WHITE);
        let mut state = RenderState::new(buf, viewport, PageResources::default(), &engine, 1);
        let ops = vec![
            ContentOperation::new("m", vec![Operand::Real(1.0), Operand::Real(1.0)]),
            ContentOperation::new("l", vec![Operand::Real(8.0), Operand::Real(1.0)]),
            ContentOperation::new("l", vec![Operand::Real(4.0), Operand::Real(8.0)]),
            ContentOperation::new("h", Vec::new()),
            ContentOperation::new("W", Vec::new()),
            ContentOperation::new("n", Vec::new()),
        ];

        for _ in 0..2 {
            for op in &ops {
                state.dispatch(op);
            }
            state.clear_current_clip();
        }

        let stats = state.path_clip_node_cache.stats();
        assert_eq!(stats.entries, 1);
        assert_eq!(stats.misses, 1);
        assert_eq!(stats.hits, 1);
    }

    #[test]
    fn document_cache_retains_transformed_path_clip_nodes_between_render_states() {
        let engine = ContentEngine::open_path(fixture("flate.pdf")).expect("open flate fixture");
        let mut cache = RenderDocumentCache::new();
        let ops = vec![
            ContentOperation::new("m", vec![Operand::Real(1.0), Operand::Real(1.0)]),
            ContentOperation::new("l", vec![Operand::Real(8.0), Operand::Real(1.0)]),
            ContentOperation::new("l", vec![Operand::Real(4.0), Operand::Real(8.0)]),
            ContentOperation::new("h", Vec::new()),
            ContentOperation::new("W", Vec::new()),
            ContentOperation::new("n", Vec::new()),
        ];

        for _ in 0..2 {
            let viewport = Viewport::new([0.0, 0.0, 10.0, 10.0], 72);
            let buf = PixelBuffer::new_filled(10, 10, WHITE);
            let mut state = RenderState::new_with_document_cache(
                buf,
                viewport,
                PageResources::default(),
                &engine,
                1,
                &mut cache,
            );
            for op in &ops {
                state.dispatch(op);
            }
            let _ = state.into_buffer_and_document_cache(&mut cache);
        }

        let stats = cache.path_clip_node_cache.stats();
        assert_eq!(stats.entries, 1);
        assert_eq!(stats.misses, 1);
        assert_eq!(stats.hits, 1);
    }

    #[test]
    fn transformed_path_clip_cache_key_includes_render_contract_identity() {
        let viewport = Viewport::new([0.0, 0.0, 10.0, 10.0], 72);
        let mut path = Path::new();
        path.move_to(1.0, 1.0);
        path.line_to(8.0, 1.0);
        path.line_to(4.0, 8.0);
        path.close();

        let first = transformed_path_clip_cache_key(
            &path,
            &Transform2D::identity(),
            PathClipCacheKeyRequest {
                viewport: &viewport,
                width: 10,
                height: 10,
                rule: FillRule::NonZero,
                render_contract_fingerprint: "contract:a",
                flatness: 0.5,
            },
        )
        .expect("cacheable clip");
        let second = transformed_path_clip_cache_key(
            &path,
            &Transform2D::identity(),
            PathClipCacheKeyRequest {
                viewport: &viewport,
                width: 10,
                height: 10,
                rule: FillRule::NonZero,
                render_contract_fingerprint: "contract:b",
                flatness: 0.5,
            },
        )
        .expect("cacheable clip");

        assert_ne!(first, second);
    }

