    #[test]
    fn merge_resources_form_xobjects_override_page() {
        let mut page_res = PageResources::default();
        page_res.xobjects.insert("X1".into(), (10, 0));
        page_res.xobjects.insert("X2".into(), (11, 0));

        let mut form_res = PageResources::default();
        form_res.xobjects.insert("X1".into(), (20, 0)); // overrides X1
        form_res.xobjects.insert("X3".into(), (30, 0)); // new

        let merged = merge_resources(form_res, &page_res);
        assert_eq!(merged.xobjects["X1"], (20, 0), "Form X1 overrides page X1");
        assert_eq!(merged.xobjects["X2"], (11, 0), "page X2 inherited");
        assert_eq!(merged.xobjects["X3"], (30, 0), "Form X3 added");
    }

    #[test]
    fn merge_resources_empty_form_yields_page_resources() {
        let mut page_res = PageResources::default();
        page_res.xobjects.insert("Im1".into(), (5, 0));
        page_res.fonts.insert("F1".into(), PdfDictionary::empty());
        page_res.font_references.insert("F1".into(), (6, 0));
        let merged = merge_resources(PageResources::default(), &page_res);
        assert_eq!(merged.xobjects["Im1"], (5, 0));
        assert!(merged.fonts.contains_key("F1"));
        assert_eq!(merged.font_references["F1"], (6, 0));
    }

    #[test]
    fn merge_resources_form_font_overrides_page_font() {
        let mut page_res = PageResources::default();
        page_res
            .fonts
            .insert("F1".into(), dict_with(&[("Tag", PdfObject::Integer(1))]));
        page_res.font_references.insert("F1".into(), (10, 0));

        let mut form_res = PageResources::default();
        form_res
            .fonts
            .insert("F1".into(), dict_with(&[("Tag", PdfObject::Integer(2))]));
        form_res.font_references.insert("F1".into(), (20, 0));

        let merged = merge_resources(form_res, &page_res);
        assert_eq!(
            merged.fonts["F1"].get_integer("Tag"),
            Some(2),
            "Form font F1 should override page font F1"
        );
        assert_eq!(
            merged.font_references["F1"],
            (20, 0),
            "Form font reference should override page font reference"
        );
    }

    #[test]
    fn font_substitution_log_survives_cache_transfer_and_records_fallback() {
        use crate::render::font_substitution_report::{
            FontSubstitutionEvent, FontSubstitutionLog, FontSubstitutionMetricPosture,
            FontSubstitutionReason,
        };

        // Simulate what happens during a render: events are recorded on the
        // RenderState's log and transferred to RenderDocumentCache.
        let mut cache = RenderDocumentCache::new();
        assert!(cache.font_substitution_log().is_empty());

        // Simulate a render pass recording two events.
        let mut state_log = FontSubstitutionLog::new();
        state_log.record(FontSubstitutionEvent::bundled_fallback(
            "Helvetica",
            "Helvetica",
            "LiberationSans-Regular",
            FontSubstitutionReason::MissingFont,
            "missing_font_dictionary",
            "implicit_standard_encoding",
            1,
            FontSubstitutionMetricPosture::MetricCompatible,
            "test-policy",
        ));
        state_log.record(FontSubstitutionEvent::bundled_fallback(
            "Symbol",
            "Symbol",
            "DejaVuSans",
            FontSubstitutionReason::BundledFallback,
            "embedded_font_unusable_or_empty",
            "SymbolEncoding",
            1,
            FontSubstitutionMetricPosture::CoverageOnly,
            "test-policy",
        ));

        // Merge into cache via take + absorb (mirrors into_buffer_and_document_cache).
        let mut merged = cache.take_font_substitution_log();
        merged.absorb(state_log);

        // Put it back by direct field access within the test module (tests have
        // access to private fields of the same crate).
        cache.font_substitution_log = merged;

        // Verify events survived.
        let log = cache.font_substitution_log();
        assert_eq!(log.events().len(), 2);
        assert_eq!(log.events()[0].requested_font, "Helvetica");
        assert_eq!(log.events()[0].reason, FontSubstitutionReason::MissingFont);
        assert_eq!(log.events()[0].page, 1);
        assert_eq!(
            log.events()[0].metric_posture,
            FontSubstitutionMetricPosture::MetricCompatible
        );
        assert_eq!(log.events()[1].requested_font, "Symbol");
        assert_eq!(
            log.events()[1].reason,
            FontSubstitutionReason::BundledFallback
        );
        assert_eq!(
            log.events()[1].metric_posture,
            FontSubstitutionMetricPosture::CoverageOnly
        );

        // Simulate a second render pass adding more events.
        let mut second_log = FontSubstitutionLog::new();
        second_log.record(FontSubstitutionEvent::bundled_fallback(
            "Helvetica",
            "Helvetica",
            "LiberationSans-Regular",
            FontSubstitutionReason::MissingFont,
            "missing_font_dictionary",
            "implicit_standard_encoding",
            2,
            FontSubstitutionMetricPosture::MetricCompatible,
            "test-policy",
        ));
        second_log.record(FontSubstitutionEvent::bundled_fallback(
            "Courier",
            "Courier",
            "LiberationMono-Regular",
            FontSubstitutionReason::MissingFont,
            "missing_font_dictionary",
            "implicit_standard_encoding",
            2,
            FontSubstitutionMetricPosture::MetricCompatible,
            "test-policy",
        ));

        let mut merged2 = cache.take_font_substitution_log();
        merged2.absorb(second_log);
        cache.font_substitution_log = merged2;

        assert_eq!(cache.font_substitution_log().events().len(), 3);
        assert_eq!(cache.font_substitution_log().events()[2].page, 2);
        assert_eq!(cache.font_substitution_log().events()[0].page, 1);

        // take_font_substitution_log resets the cache log.
        let taken = cache.take_font_substitution_log();
        assert_eq!(taken.events().len(), 3);
        assert!(cache.font_substitution_log().is_empty());
    }

    #[test]
    fn font_replacement_selection_labels_external_provider_sources() {
        let bytes = b"font";
        let user_registered = FontMatch {
            family_name: "Registered Sans",
            lookup_name: "RegisteredSans-Regular".to_string(),
            source: FontProviderSource::UserRegistered,
            bytes: std::borrow::Cow::Borrowed(&bytes[..]),
            synthetic_bold: false,
            synthetic_italic: false,
            match_reason: "user_registered_direct_match",
        };
        let selection = FontReplacementSelection::from_font_match(&user_registered);
        assert_eq!(selection.reason, FontSubstitutionReason::DocumentProvided);
        assert_eq!(selection.resolution_source, "user_registered");
        assert!(selection.allowed_in_exact_contract);

        let system_mapping = FontMatch {
            family_name: "System Sans",
            lookup_name: "SystemSans-Regular".to_string(),
            source: FontProviderSource::DeterministicSystemMapping,
            bytes: std::borrow::Cow::Borrowed(&bytes[..]),
            synthetic_bold: false,
            synthetic_italic: false,
            match_reason: "configured_system_mapping",
        };
        let selection = FontReplacementSelection::from_font_match(&system_mapping);
        assert_eq!(
            selection.reason,
            FontSubstitutionReason::DeterministicSystemMapping
        );
        assert_eq!(selection.resolution_source, "deterministic_system_mapping");
        assert!(selection.allowed_in_exact_contract);
    }

    // ---- Focused tests proving the plan path is active for all supported content types ----

    #[test]
    fn plan_path_active_for_text_page_matches_immediate() {
        // This test proves text pages go through the packed plan path (via
        // render_page_display_list_with_mode) and produce identical output to
        // the default page-render entry point.
        let engine = ContentEngine::open_bytes(simple_nonembedded_font_pdf("Helvetica"))
            .expect("open text fixture");
        let list = engine
            .build_page_display_list(1, 72)
            .expect("build display list");
        assert!(list.is_fully_supported());
        assert!(list.stats.native_text_ops > 0, "must have native text ops");
        // The plan path is now universally invoked for all fully-supported lists.
        let baseline = engine.render_page(1, 72).expect("default page render");
        let plan_result =
            PageRenderer::render_page_display_list_with_mode(&engine, 1, 72, RenderMode::Compat)
                .expect("plan render");
        assert_same_pixels(&baseline, &plan_result);
    }

